/* 兜底方案：强制居中且不重复 */
.input-btn-plus, .input-btn-mic, .input-btn-sticker, .input-btn-ai, .send-btn-custom {
  background-color: transparent !important;
  background-position: center !important;
  background-repeat: no-repeat !important; /* <--- 修复了这里的拼写错误 */
