/* 隐藏原有难看的 SVG */
.input-btn-plus svg, .input-btn-mic svg, .input-btn-sticker svg, .input-btn-ai svg, .send-btn-custom svg {
  opacity: 0 !important;
}

/* =========================================
   已读/未读状态文字自定义替换
========================================= */
/* 首先强制隐藏掉原生输出的文本内容，并开启定位以便伪元素显示 */
.msg-status-custom {
  font-size: 0 !important; /* 利用 0 号字体隐藏原本的 "已发送" / "已读" 中文 */
  display: inline-block !important;
  color: #888888 !important; /* 统一基础颜色为您要求的灰色 */
  margin-top: 2px !important;
}

/* --- 1. 已发送 (未读) 状态：딩동 --- */
.msg-status-custom.is-sent::after {
  content: "딩동" !important;
  font-size: 11px !important; /* 恢复您想要的字体大小 */
  color: #888888 !important; 
  display: inline-block !important;
}

/* --- 2. 已读 状态：보고 싶어요 --- */
.msg-status-custom.is-read::after {
  content: "보고 싶어요" !important;
  font-size: 11px !important; 
  color: #888888 !important; /* 如果已读需要变色，可以改这里 */
  display: inline-block !important;
}

/* =========================================
   转账卡片 (核弹级重构：100% 绝对坐标还原手稿)
========================================= */

/* 1. 画布设定：强行把卡片变成一块 240x104 的画板 */
.msg-transfer-card {
  position: relative !important;
  display: block !important;
  width: 240px !important;
  height: 104px !important; /* 72px 黑底 + 32px 灰底 */
  background: #000000 !important;
  border: none !important;
  border-radius: 6px !important;
  padding: 0 !important;
  margin: 0 !important;
  overflow: hidden !important; 
