==================================================== */
.chat-detail-screen {
  position: absolute !important;
  top: 0 !important;
  right: 0 !important;
  left: 75px !important;
  bottom: 20px !important;
  width: auto !important;
  height: auto !important;
  min-height: 0 !important;
  max-height: none !important;
