/* ============================================
   顶栏区域
   ============================================ */

/* ---- 顶栏背景：淡灰棕色（无边框） ---- */
.chat-header-custom {
  background: #55504b !important;
  border-top: none !important;
  border-bottom: none !important;
  box-shadow: none !important;
  border: none !important;
}

/* ==========================================
   副标题文案（前面加图标）
   ⚠️ 改字：修改 content 中的文字即可
   ⚠️ 调色：color 数值 #b5e6c3 薄荷绿
   ⚠️ 位置：left 控制左右，top 控制上下
   ========================================== */
.chat-header-custom::after {
  content: "" !important;
  color: #b5e6c3 !important;
  position: absolute;
  left: calc(2px + 41px);
  top: calc(100% - 26px);
  font-size: 11px;
  white-space: nowrap;
  z-index: 99;
  display: flex !important;
  align-items: center !important;
  gap: 4px !important;
}

/* 用伪元素的 ::before 加小图标 */
.chat-header-custom::before {
  content: "" !important;
  position: absolute;
  left: calc(2px + 41px);
  top: calc(100% - 23px);
  width: 9px !important;
  height: 9px !important;
  background: url("https://i.imgs.ovh/2026/07/19/b7ccba91e3fa681b647398ae703d6d88.png") no-repeat center / contain !important;
  pointer-events: none !important;
  z-index: 100 !important;
}

/* 副标题文字右移，给图标让位 */
