  background-color: #5f5049 !important; 
  border-radius: 13px !important;
  width: 255px !important;
  height: 33px !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  margin-top: 0px !important;
