  font-size: 14px !important;
  font-weight: normal !important;
  top: 50% !important;
  left: -8% !important;
  transform: translate(0px, -50%) !important; 
  z-index: 10 !important;
  pointer-events: none !important;  
  white-space: nowrap !important;
  transition: opacity 0.15s ease !important; 
}

.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown))::after,
.input-action-bar-custom:has(.input-box-custom:not(:empty))::after {
  opacity: 0 !important;
  visibility: hidden !important;
}

/* ====================================================
16. 素净模式气泡
==================================================== */
.msg-bubble-wrapper {
  position: relative !important;
  width: 100% !important;
}

.msg-plain-me, .msg-plain-them {
  display: inline-block !important;
  width: max-content !important;
  max-width: 100% !important;
}

.msg-plain-me {
  background-color: #5f5049 !important; 
  border: none !important;
  border-radius: 16px !important;
  padding: 6px 12px !important;
  box-shadow: none !important;
  word-break: break-word !important;
}

.msg-plain-me, .msg-plain-me * {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  font-size: 14px !important; 
  line-height: 1.3 !important; 
}

.msg-me .msg-content-stack {
  margin-right: 32px !important;
}

.msg-avatar-me-container {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  position: absolute !important;
  width: 28px !important;
  height: 28px !important;
  top: -15px !important; 
  right: 2px !important; 
  margin: 0 !important;
  padding: 0 !important;
  z-index: 10 !important;
}

.msg-avatar-me-inner {
  width: 100% !important;
  height: 100% !important;
  border-radius: 50% !important;
}

.msg-bubble-wrapper.msg-me:not(.is-first):not(.is-single) .msg-avatar-me-container {
  display: none !important;
}

.msg-plain-them {
  background-color: #d1efed !important; 
  border: 1px solid #ffffff !important; 
  border-radius: 16px !important;
  padding: 5px 11px !important;
  box-shadow: none !important;
  word-break: break-word !important;
}

.msg-plain-them, .msg-plain-them * {
  color: #5f5049 !important; 
  -webkit-text-fill-color: #5f5049 !important;
  font-size: 14px !important; 
  line-height: 1.3 !important; 
}

.msg-avatar-them-container {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  position: absolute !important;
  width: 30px !important;
  height: 30px !important;
  top: 0 !important;
  left: 12px !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 10 !important;
}

.msg-avatar-them-inner {
  width: 100% !important;
  height: 100% !important;
  border-radius: 50% !important;
}

.msg-bubble-wrapper.msg-them:not(.is-first):not(.is-single) .msg-avatar-them-container {
  display: none !important;
}

.msg-them.is-first::after,
.msg-them.is-single::after {
  content: "" !important;
  position: absolute !important;
  width: 45px !important;
  height: 45px !important;
  top: -7px !important;
  left: 4px !important;
  background-image: url('https://nos.netease.com/ysf/c1880fc734fb53ebc8bffdbc03fc5c0e.WEBP') !important;
  background-size: contain !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  z-index: 100 !important;
  pointer-events: none !important;
}

.msg-them.is-first .msg-content-stack,
.msg-them.is-single .msg-content-stack {
  margin-top: 38px !important;
  margin-left: 12px !important;
}

.msg-them.is-mid .msg-content-stack,
.msg-them.is-last .msg-content-stack {
  margin-left: 12px !important;
}

.msg-plain-me > svg, .msg-plain-me::before, .msg-plain-me::after,
.msg-plain-them > svg, .msg-plain-them::before, .msg-plain-them::after {
  display: none !important;
}

/* ====================================================
17. 独立引用条
==================================================== */
.msg-reply-block { 
  display: none !important; 
}

.msg-reply-block-detached {
  display: flex !important;
  max-width: 60vw !important; /* 强制引用框不能无限变宽 */
  overflow: hidden !important;
}

/* ✅ 修复：精准选择文字区域进行截断，去除了导致图片消失的全局通配符 */
.msg-reply-block-detached div[class*="text"],
.msg-reply-block-detached div[class*="content"],
.msg-reply-detached-text {
  min-width: 0 !important; /* 核心魔法：只让文字容器允许被压缩，触发省略号 */
  overflow: hidden !important;
  text-overflow: ellipsis !important; /* 超出变成省略号 */
  white-space: nowrap !important; /* 强制不换行 */
  max-width: 100% !important;
}

/* ✅ 额外保护：强行锁定引用框内的图片大小，确保不被挤没 */
div[class*="message"] .msg-reply-block-detached img {
  display: inline-block !important;
  flex-shrink: 0 !important; /* 禁止被 Flex 挤压 */
  width: auto !important;
  height: auto !important;
  max-width: 40px !important;
  max-height: 40px !important;
  min-width: 15px !important;
}

.msg-reply-detached-name::before {
  content: "" !important;
  display: inline-block !important;
  width: 11px !important;
  height: 11px !important;
  background-color: #7b6b66 !important;
  -webkit-mask-image: url('https://nos.netease.com/ysf/73ee60fcbf21b1d18f29e20726978a0f.svg') !important;
  mask-image: url('https://nos.netease.com/ysf/73ee60fcbf21b1d18f29e20726978a0f.svg') !important;
  -webkit-mask-size: contain !important;
  mask-size: contain !important;
  -webkit-mask-position: center !important;
  mask-position: center !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-repeat: no-repeat !important;
  margin-right: 4px !important; 
  vertical-align: middle !important;
  transform: translateY(-1px) !important; 
}

