/* nuojiji-bubble-config: {"themeStyle":"qq","bubbleStyle":"#06C755","partnerBubbleStyle":"#ffffff","bubbleTextColor":"#ffffff","partnerBubbleTextColor":"#000000","avatarSize":38,"avatarShape":"circle"} */

/*⁣⁠‍​‍​⁠​‌‌‌​‌‌⁠⁠‍​​⁠​⁠​⁠⁠‌‍​⁠‌​⁠⁠​⁠⁠‍‍⁠‌‌‌‍⁠​⁠​​‍​​​⁠⁠​​‍‍‍⁠⁠⁠​‌⁠⁣ =================================== */
/* 顶栏高度变量 */
/* =================================== */
:root{
  --new-top-bar-height:105px;
  --new-top-content-y:53px;
}

/* =================================== */
/* 底栏样式变量 */
/* =================================== */
:root{
  --input-top-space:3px;
  --bottom-lift-space:20px;

  --box-border-width:1.5px;
  --box-border-radius:5px;
  --box-right-space:66px;
  --box-left-space:-10px;
  --box-top-offset:7px;
  --box-bottom-offset:7px;

  --input-box-pull-left:-27px;
  --input-box-pull-right:-37px;
  --input-text-padding-left:10px;

  --right-btn-size:28px;
  --right-mic-size:18px;

  --typing-btn-bottom:1.5px;
}
/* 当底栏包含引用预览栏时，底部距离抬高 4px */
.input-area-custom:has(.input-reply-preview-bar) {
  padding-bottom: calc(var(--bottom-lift-space) + 4px) !important;
}
/* =================================== */
/* 全局调位置 */
/* =================================== */
:root{
  --wechat-title-x:35px;
  --wechat-title-y:5px;
  --btn-back-translate-x:0px;
  --btn-back-translate-y:3px;
  --btn-info-translate-x:0px;
  --btn-info-translate-y:5px;

  --unread-num-top:13px;
  --unread-num-left:18px;
  --unread-num-font-size:10px;
  --unread-num-font-weight:700;
  --unread-num-padding:0 7px;
  --unread-num-height:18px;

  --voice-btn-x:-13px;
  --voice-btn-y:-5px;
  --voice-btn-size:28px;

  --btn-mic-x:28px;
  --btn-mic-y:0px;
  --btn-sticker-x:26px;
  --btn-sticker-y:0px;
  --btn-ai-send-x:22px;
  --btn-ai-send-y:0px;

  --fake-sticker-x:26px;
  --fake-sticker-y:0px;
  --real-send-x:22px;
  --real-send-y:0px;

  --gen-plus-x:24px;
  --gen-icon-y:49.5%;
  --gen-sticker-x:-16px;
  --gen-sticker-y:50.5%;
  --gen-mic-x:-77px;
  --gen-mic-y:25.8px;
}

/* =================================== */
/* 全局日间模式 */
/* =================================== */
@media (prefers-color-scheme: light) {
