/*⁣⁠‍​‍​⁠​‌‌‌​‌‌⁠⁠‍​​⁠​⁠​⁠⁠‌‍​⁠‌​⁠⁠​⁠⁠‍‍⁠‌‌‌‍⁠​⁠​​‍​​​⁠⁠​​‍‍‍⁠⁠⁠​‌⁠⁣ =========================================================
   🍎 iOS 26 iMessage 真·独立立体液态玻璃版 (引用条复位+水波透镜版)
   ========================================================= */

/* ═══════════════════════════════════════════════════════════
   ✨ 小白专属极简自定义配置区 (不同机型一键适配，只需改这里！)
   ═══════════════════════════════════════════════════════════ */
:root {
  /* 🌟 【类别 1】：顶栏左右两端气泡【返回键 & 右侧设定键】高度与大小 (归为一类，一起调整)
        (默认 44px。若觉两端偏大气泡可改 40px，想更大改 46px。两端会自动等高同步变动) */
  --top-side-bubbles-size: 44px;

  /* 🌟 【类别 2】：顶栏大头像【尺寸大小】
        (默认 60px。改小可填 52px / 54px，改大可填 64px / 68px) */
  --top-avatar-size: 60px;

  /* 🌟 【类别 3】：顶栏中间【昵称气泡】大小尺寸 (自成一类，完全独立调节) */
  --top-name-bubble-height: 34px;       /* 昵称气泡高度 (默认 34px，想小巧填 30px，想宽大填 38px) */
  --top-name-bubble-padding-x: 15px;    /* 昵称气泡左右宽度留白 (默认 15px，想更长填 18px) */
  --top-name-bubble-font-size: 14.5px;  /* 昵称文字大小 (默认 14.5px，想字小填 13.5px) */

  /* 🌟 【类别 4】：顶栏整体气泡【上下垂直位置高低微调】
        (针对不同机型灵动岛/刘海屏高低差：正数向下沉，负数向上提。例如: 4px 或 -4px) */
  --top-bubbles-offset-y: 0px;

  /* 🌟 【类别 5】：低栏加号键与输入框【整体上调/下调高度】(已彻底修复可动)
        (必须带 px 单位！数值越大越往上提，负数往下沉。例如: 10px 向上提，-8px 向下沉) */
  --bottom-bar-offset-y: 0px;
}

/* ═══════════════════════════════════════════════════════════
   1. 基础配置变量区
   ═══════════════════════════════════════════════════════════ */
:root {
  /* 🎨 气泡颜色 (完全保持原版) */
  --bubble-me-bg: #1E90FF;        /* 我方气泡颜色 (经典绿) */
