/* 🍓文字图 by小芋 */
:root {
  --msg-sim-border: 1px solid rgba(213, 213, 213, 0.03);
  --msg-sim-shadow: 0 0 3px rgba(0, 0, 0, 0.03), 
inset 0px 0px 1px 1px rgba(255,255,255,0.07);
  --msg-sim-img1: url("https://imgbed.heliar.top/i/4-KM5LMe4q7bkCHP_IMG_1996.jpeg");
  --msg-sim-img2: url("https://imgbed.heliar.top/i/UGHpTDTdy4zDZZwn_IMG_1995.jpeg");
  --msg-sim-img3: url("https://imgbed.heliar.top/i/RxiTcCPGvDuJwdJp_IMG_1994.jpeg");
}
/* 文字图 */
.msg-sim-card * {
  display: none !important;
}
.msg-sim-card {
  position: relative !important;
  overflow: visible !important;
  width: 160px !important;
  height: 210px !important;
  background-origin: border-box !important;
  background-clip: border-box !important;
  background-image: var(--msg-sim-img1) !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  border-radius: 10px !important;
  border: var(--msg-sim-border) !important;
  box-shadow: var(--msg-sim-shadow) !important;
  margin-right: 26px !important;
}
.msg-sim-card::before {
  background-image: var(--msg-sim-img2) !important;
  transform: translateX(20px) rotate(2.5deg) scale(0.9) !important;
  z-index: -1 !important;
}
.msg-sim-card::after {
  background-image: var(--msg-sim-img3) !important;
  transform: translateX(37px) rotate(4.5deg) scale(0.8) !important;
  z-index: -2 !important;
}
.msg-sim-card::before,
.msg-sim-card::after {
  content: "" !important;
  position: absolute !important;
  inset: -0.5px  !important;
  width: 100% !important;
  height: 100% !important;
  border-radius: 10px !important;
  border: var(--msg-sim-border) !important;
  box-shadow: var(--msg-sim-shadow) !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-color: transparent !important;
  pointer-events: none !important;
}

:root {
  --translation-always-show: 1;
}

/* 1. 隐藏 bubble 内部的原翻译块 */
.msg-translation-wrapper {
  display: none !important;
}

/* 2. 启用 bubble 外部的独立翻译气泡 */
.msg-translation-detached {
  display: block !important;
  margin-top: -12px !important;
  max-width: 95% !important;
  width: fit-content !important;
  min-width: 0 !important;      
  box-sizing: border-box !important;
}

/* 3. 独立翻译气泡内容 — 优化文字描边平滑度 */
.msg-translation-detached-content {
  background: transparent !important;
  color: #ffffff !important;
  font-weight: bold !important;
  text-shadow: 
    1px  1px 0 #000,
   -1px -1px 0 #000,
    1px -1px 0 #000,
   -1px  1px 0 #000,
    1px  0px 0 #000,
   -1px  0px 0 #000,
    0px  1px 0 #000,
    0px -1px 0 #000 !important;
  padding: 3px 6px 3px 6px !important;
  border-radius: 0px !important;
  box-shadow: none !important;  
  font-size: 15px !important;
  line-height: 1.4 !important;
  word-break: break-word !important;
  position: relative !important;
  min-width: 0 !important;      
  box-sizing: border-box !important;
}

/* 4. 左右位置 */
.msg-translation-detached-them { 
  align-self: flex-start !important; 
  margin-left: 15px !important;    
}
.msg-translation-detached-me   { align-self: flex-end !important; }

