.chat-detail-screen .input-area-custom .input-btn-plus {
    opacity: 0 !important;
    pointer-events: auto !important;
    position: absolute !important;
    z-index: 3 !important;
    top: 52px !important;
    right: 25px !important;
    width: 32px !important; height: 32px !important; padding: 0 !important; margin: 0 !important;
}

/* 中间：AI按钮 */
.chat-detail-screen .input-area-custom .input-btn-ai {
    opacity: 0 !important;
    pointer-events: auto !important;
    position: absolute !important;
    z-index: 3 !important;
    top: 0px !important;
    left: 10px !important;
    width: 32px !important; height: 32px !important; padding: 0 !important; margin: 0 !important;
}

/* 最右边：发送按钮 */
.chat-detail-screen .input-area-custom .send-btn-custom {
    opacity: 0 !important;
    pointer-events: auto !important;
    position: absolute !important;
    z-index: 3 !important;
    top: 0px !important;
    right: 15px !important;
    width: 32px !important; height: 32px !important; padding: 0 !important; margin: 0 !important;
}

/* 控制台定位 */
.chat-detail-screen .nuo-console-shell {
    position: absolute !important;
    bottom: 100% !important;
    left: 16px !important;
    right: 16px !important;
    z-index: 99 !important;
    width: auto !important;
    pointer-events: auto !important;
    margin-bottom: 2px !important; /* ❤️ 调整控制台与底栏输入框的距离，正数变大间距 */
}

/* ================= 气泡样式区域 ================= */

/* 对方气泡 */
.chat-detail-screen .bubble-them-custom,
.chat-detail-screen .msg-plain-them {
    background: #ffffff !important; /* ❤️ 可修改对方气泡背景色 */
    border: 1.5px solid #f8c8d8 !important; /* ❤️ 可调整边框粗细和颜色 */
    box-shadow: 0 2px 6px rgba(248, 200, 216, 0.25) !important; /* ❤️ 可调整阴影效果 */
    color: #4a3b40 !important; /* ❤️ 可修改对方文字颜色 */
    position: relative !important;
    overflow: visible !important;
}

/* 我方气泡 */
.chat-detail-screen .bubble-me-custom,
.chat-detail-screen .msg-plain-me {
    background: #fce4ec !important; /* ❤️ 可修改我方气泡背景色 */
    border: none !important;
    box-shadow: 0 2px 6px rgba(252, 228, 236, 0.3) !important; /* ❤️ 可调整阴影 */
    color: #4a3b40 !important; /* ❤️ 可修改我方文字颜色 */
    position: relative !important;
    overflow: visible !important;
}

/* 连发尖角 */
.chat-detail-screen .bubble-them-custom.first { border-top-left-radius: 4px !important; } /* ❤️ 可修改对方气泡首条左上圆角，0为直角 */
.chat-detail-screen .bubble-me-custom.first { border-top-right-radius: 4px !important; } /* ❤️ 可修改我方气泡首条右上圆角 */

/* 文字气泡胶囊感 */
.chat-detail-screen .bubble-me-custom,
.chat-detail-screen .bubble-them-custom,
.chat-detail-screen .msg-plain-me,
.chat-detail-screen .msg-plain-them {
    padding: 3px 16px !important; /* ❤️ 可调整文字气泡上下和左右内边距，改变胶囊高度和宽度感 */
    border-radius: 16px !important; /* ❤️ 可调整气泡圆角大小，0为直角，值越大越圆 */
    background-clip: padding-box !important;
    margin: 0 !important;
    min-height: auto !important;
}

/* 非文字消息去除气泡外壳 */
.chat-detail-screen .bubble-me-custom:has(.voice-msg),
.chat-detail-screen .bubble-them-custom:has(.voice-msg),
.chat-detail-screen .bubble-me-custom:has([class*="call"]),
.chat-detail-screen .bubble-them-custom:has([class*="call"]),
.chat-detail-screen .bubble-me-custom:has(.msg-theater-card),
.chat-detail-screen .bubble-them-custom:has(.msg-theater-card),
.chat-detail-screen .bubble-me-custom:has(.msg-transfer-card),
.chat-detail-screen .bubble-them-custom:has(.msg-transfer-card),
.chat-detail-screen .bubble-me-custom:has(.msg-loc-card),
.chat-detail-screen .bubble-them-custom:has(.msg-loc-card),
.chat-detail-screen .bubble-me-custom:has(.msg-image-wrapper),
.chat-detail-screen .bubble-them-custom:has(.msg-image-wrapper),
.chat-detail-screen .bubble-me-custom:has(.gift-ig-container),
.chat-detail-screen .bubble-them-custom:has(.gift-ig-container),
.chat-detail-screen .bubble-me-custom:has([class*="sticker"]),
.chat-detail-screen .bubble-them-custom:has([class*="sticker"]),
.chat-detail-screen .bubble-me-custom:has([class*="gif"]),
.chat-detail-screen .bubble-them-custom:has([class*="gif"]),
.chat-detail-screen .bubble-me-custom:has([class*="emoji"]),
.chat-detail-screen .bubble-them-custom:has([class*="emoji"]),
.chat-detail-screen .bubble-me-custom:has(img),
.chat-detail-screen .bubble-them-custom:has(img),
.chat-detail-screen .bubble-me-custom:has(video),
.chat-detail-screen .bubble-them-custom:has(video),
.chat-detail-screen .bubble-me-custom:has(svg),
.chat-detail-screen .bubble-them-custom:has(svg) {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin: 0 !important;
}
/* 清理特殊卡片和图片的尾巴 */
.chat-detail-screen .bubble-me-custom:has(.voice-msg)::before,
.chat-detail-screen .bubble-them-custom:has(.voice-msg)::before,
.chat-detail-screen .bubble-me-custom:has(.voice-msg)::after,
.chat-detail-screen .bubble-them-custom:has(.voice-msg)::after,
.chat-detail-screen .bubble-me-custom:has([class*="call"])::before,
.chat-detail-screen .bubble-them-custom:has([class*="call"])::before,
.chat-detail-screen .bubble-me-custom:has([class*="call"])::after,
.chat-detail-screen .bubble-them-custom:has([class*="call"])::after,
.chat-detail-screen .bubble-me-custom:has(img)::before,
.chat-detail-screen .bubble-them-custom:has(img)::before,
.chat-detail-screen .bubble-me-custom:has(img)::after,
.chat-detail-screen .bubble-them-custom:has(img)::after {
    display: none !important;
}

/* 气泡间距 */
.chat-detail-screen .bubble-me-custom,
.chat-detail-screen .bubble-them-custom,
.chat-detail-screen .msg-plain-me,
.chat-detail-screen .msg-plain-them {
    margin-bottom: 8px !important; /* ❤️ 可调整气泡之间的上下间距 */
}
.chat-detail-screen .msg-bubble-wrapper {
    margin-bottom: 8px !important; /* ❤️ 可调整消息气泡外层包裹的间距 */
}

/* ===== 双方头像大小 ===== */
:root {
    --avatar-size: 40px !important; /* ❤️ 可调整双方头像的尺寸 */
    --avatar-radius: 50% !important; /* ❤️ 可改为其他数值改变圆角，50%为圆形 */
    --plain-avatar-size: 40px !important; /* ❤️ 纯文本模式下头像尺寸 */
    --avatar-margin: 12px !important; /* ❤️ 头像与气泡的间距 */
    --plain-avatar-gap: 12px !important; /* ❤️ 纯文本头像间距 */
}

/* ===== 99+ 徽章微调 ===== */
.nuo-chat-header-unread-num {
    margin-top: -2px !important; /* ❤️ 微调未读数字的垂直位置，负数上移，正数下移 */
}

/* ===== 引用预览条抬高 ===== */
.chat-detail-screen .input-area-custom .input-reply-preview-bar {
    position: absolute !important;
    bottom: 100% !important;
    transform: translateY(-8px) !important; /* ❤️ 可调整引用预览条与输入框的垂直距离，-8px 为更靠近，正值推远 */
    left: 0 !important;
    right: 0 !important;
    width: 100% !important;
    z-index: 100 !important;
    min-height: 32px !important; 
    padding: 6px 12px !important;
    display: flex !important;
    align-items: center !important;
    box-sizing: border-box !important;
}

/* ===== 表情/贴纸面板抬高 ===== */
.chat-detail-screen .input-area-custom [class*="emoji"],
.chat-detail-screen .input-area-custom [class*="sticker"],
.chat-detail-screen .input-area-custom [class*="picker"],
.chat-detail-screen .input-area-custom [class*="panel"] {
    position: absolute !important;
    bottom: 100% !important;
    transform: translateY(-20px) !important; /* ❤️ 可调整表情面板与输入框的距离，-20px 更靠近，正值推远 */
    left: 0 !important;
    right: 0 !important;
    width: 100% !important;
    z-index: 100 !important;
}

/* ✅ 只改聊天表情包 · 绝对不碰头像，也绝不误伤带有引用的消息 ✅ */
/* 核心：选中不包含头像的气泡，并且严格排除掉包含引用框(reply)的气泡 */

/* 只清除纯表情包的气泡边框、背景、内边距、阴影 */
div[class*="message"] div[class*="bubble"]:has(img):not(:has([class*="avatar"])):not(:has([class*="reply"])) {
  background: transparent !important; /* 清除气泡背景色 */
  border: none !important; /* 彻底去掉边框线 */
  box-shadow: none !important; /* 清除气泡的立体阴影 */
  padding: 0 !important; /* 消除图片和气泡之间的空隙 */
  border-radius: 0 !important; /* 去掉气泡圆角，如需保留可删除此行 */
  outline: none !important; /* 清除可能的外轮廓线 */
}

/* 只控制纯表情包的尺寸，完全不影响头像，也不影响引用里的小图片 */
div[class*="message"] div[class*="bubble"]:not(:has([class*="avatar"])):not(:has([class*="reply"])) img {
  width: 80px !important;
  height: 80px !important;
  max-width: 80px !important;
  max-height: 80px !important;
  transform: scale(1.0) !important;
  /* 可选补充：去掉图片自带的圆角/边框，不需要可删除 */
  border-radius: 0 !important;
  border: none !important;
}


/* ====================================================
0. 全局变量设定 (Header 与其他调整)
==================================================== */
:root {
  --chat-header-height: 100px;       
  --chat-header-bg: #E5F4F0;         /* 薄荷绿底色 */
  --chat-header-border: transparent; 
  --chat-header-blur: 0px;           

  --plain-gap-between-groups: 18px;  
  --plain-gap-within-group: 5px;     
  --plain-content-max-width: 75%;    

  --timestamp-margin: 20px 0 35px;
  --system-msg-margin: 35px 0 35px;

  /* 时间戳和系统消息文字颜色改为冷咖色 */
  --timestamp-color: #7b6b66;
  --system-msg-color: #7b6b66;

  /* 17. 独立引用条的外观设定 */
  --reply-detached-bg: #FFFFFF;
  --reply-detached-border: 1px solid #7b6b66;
  --reply-detached-border-left: 1px solid #7b6b66; 
  --reply-detached-radius: 6px;
  --reply-detached-padding: 3px 8px;
  --reply-detached-margin-top: 2px;
  --reply-detached-name-color: #7b6b66; 
  --reply-detached-text-color: #7b6b66; 
  --reply-detached-name-size: 11px;
  --reply-detached-text-size: 11px;

  /* ✅ 修复：限制最大宽度为屏幕宽度的 60% */
  --reply-detached-max-width: 60vw;
  --reply-detached-gap: 2px;

  --transfer-icon-bg: transparent;
  --transfer-me-icon-bg: transparent;
  --transfer-them-icon-bg: transparent;
}

/* 强制清除可能残留的原生顶栏阴影 */
.chat-header-custom, .glass-header {
  box-shadow: none !important;
  border-bottom: none !important;
}

/* ====================================================
1. 锁死最底层的网页，铺上薄荷绿的底
==================================================== */
html, body {
  background-color: #E5F4F0 !important;
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  height: 100% !important;
  overflow: hidden !important;
}

/* ====================================================
2. 魔法核心：整个聊天界面主体强行固定在右上角
==================================================== */
.chat-detail-screen {
  position: absolute !important;
  top: 0 !important;
  right: 0 !important;
  left: 75px !important;
  bottom: 20px !important;
  width: auto !important;
  height: auto !important;
  min-height: 0 !important;
  max-height: none !important;
  transform: translateZ(0) !important;
  contain: layout paint !important;
  clip-path: inset(0) !important;
  background-color: #E5F4F0 !important;
  overflow: hidden !important;
}

/* ====================================================
3. 绘制底部纯白底板
==================================================== */
html::after {
  content: "" !important;
  position: fixed !important; 
  bottom: 0 !important; 
  left: 65px !important;
  width: calc(100% - 65px) !important; 
  height: 20px !important;
  background-color: #E5F4F0 !important;
  z-index: 0 !important; 
  pointer-events: none !important;
}

/* ====================================================
