  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  box-shadow: 0 3px 10px rgba(73, 60, 55, 0.12) !important;
  z-index: 2 !important;
  pointer-events: none !important;
}

/* ====================================================
5. 头像右下角角标
==================================================== */
body::after {
  content: "" !important;
  position: fixed !important;
  top: 77px !important;
  left: 49px !important; 
  width: 14px !important;
  height: 14px !important;
  background-image: url('https://nos.netease.com/ysf/068a93c58e13510d47012b25f2449171.png') !important;
