  top: -15px !important; 
  right: 2px !important; 
  margin: 0 !important;
  padding: 0 !important;
  z-index: 10 !important;
}

.msg-avatar-me-inner {
  width: 100% !important;
  height: 100% !important;
  border-radius: 50% !important;
}

.msg-bubble-wrapper.msg-me:not(.is-first):not(.is-single) .msg-avatar-me-container {
  display: none !important;
}

.msg-plain-them {
  background-color: #d1efed !important; 
