}

/* ====================================================
12. 隐藏底栏所有按钮原生图标
==================================================== */
.input-btn-plus svg, .input-btn-plus img,
.input-btns-right svg, .input-btns-right img,
.send-btn-custom svg, .send-btn-custom img,
