.nj-chat-tab-header-title-btn > * {
    display: none !important;
}
.nj-chat-tab-header-title-btn::before {
    content: var(--header-title) !important;
}
/* 独立倒三角 */
.nj-chat-tab-header-title-btn::after {
    content: var(--header-arrow) !important;
    font-size: 11px !important;
    font-weight: 900 !important;
    margin-left: 0px !important;
    color: inherit !important;
}
/* 修改顶栏自定义文字颜色为 #585858 */
.nj-chat-tab-header-back::before {
    color: #585858 !important;
}
.nj-chat-tab-header-title-btn::before {
    color: #585858 !important;
}
.nj-chat-tab-header-title-btn::after {
    color: #585858 !important;
}

/* 右上角头像按钮 */
.nj-chat-tab-header-edit {
    position: absolute !important;
    right: 22px !important;
    top: 47px !important;
    width: 20px !important;
    height: 20px !important;
    color: transparent !important;
    background-image: var(--header-avatar) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    border-radius: 50% !important;
    cursor: pointer !important;
    z-index: 10 !important;
}
.nj-chat-tab-header-edit svg,
.nj-chat-tab-header-edit img {
    display: none !important;
}
/* ========== 强制统一定位参考 ========== */
#messaging-chat-tab {
    position: relative !important;
    border: none !important;
    box-shadow: none !important;
}

/* 清除三个装饰容器的所有可能产生定位上下文的属性 */
.nj-chat-tab-decor-top,
.nj-chat-tab-notes,
.nj-chat-tab-decor-mid {
    position: static !important;      /* 避免创建新的定位上下文 */
    transform: none !important;       /* 关键：清除 transform */
    will-change: auto !important;     /* 清除 will-change */
    display: block !important;
    height: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    background: transparent !important;
    overflow: visible !important;
}

/* 隐藏这些容器内的原生子元素 */
.nj-chat-tab-decor-top > *,
.nj-chat-tab-notes > *,
.nj-chat-tab-decor-mid > * {
    display: none !important;
}

/* ========== 所有图片相对于 #messaging-chat-tab 绝对定位 ========== */
/* 使用 decor-top 和 decor-mid 两个容器，每个两个伪元素，共四张图片 */
.nj-chat-tab-decor-top::before,
.nj-chat-tab-decor-top::after,
.nj-chat-tab-decor-mid::before,
.nj-chat-tab-decor-mid::after {
    content: "" !important;
    position: absolute !important;
    top: var(--decor-top-offset) !important;
    width: var(--decor-size) !important;
    height: var(--decor-size) !important;
    border-radius: 8px !important;
    border: 1.7px solid #ffffff !important;
    box-shadow: 0 2px 12px rgba(0,0,0,0.15) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    transform: rotate(0deg) !important;
    z-index: 10 !important;
}

/* 四张图片水平位置及独立旋转 */
.nj-chat-tab-decor-top::before {
    left: var(--decor-left-1) !important; /* 图片太分散想靠近的调这里‼️‼️*/
    transform: rotate(-4deg) !important;
    background-image: var(--decor-img-1) !important;
}
.nj-chat-tab-decor-top::after {
    left: var(--decor-left-2) !important;
    transform: rotate(4deg) !important;
    background-image: var(--decor-img-2) !important;
}
.nj-chat-tab-decor-mid::before {
    left: var(--decor-left-3) !important;
    transform: rotate(-3deg) !important;
    background-image: var(--decor-img-3) !important;
}
.nj-chat-tab-decor-mid::after {
    left: var(--decor-left-4) !important;
    transform: rotate(4deg) !important;
    background-image: var(--decor-img-4) !important;
}

/* 确保 decor-mid 容器不干扰布局（高度0，无overflow） */
.nj-chat-tab-decor-mid {
    display: block !important;
    height: 0 !important;
    overflow: visible !important;
    position: static !important;
}

/* 彻底隐藏原生占位符 */
.nj-chat-tab-search input::placeholder {
    visibility: hidden !important;
    opacity: 0 !important;
    color: transparent !important;
}

/* 隐藏输入文字与光标 + 输入框完全透明 */
.nj-chat-tab-search input {
    color: transparent !important;
    caret-color: transparent !important;
    background: transparent !important;   /* 背景透明 */
    border: none !important;              /* 无边框 */
    outline: none !important;             /* 无外轮廓 */
    box-shadow: none !important;          /* 无阴影 */
}

/* 自定义展示文案 */
.nj-chat-tab-search::after {
    content: var(--search-placeholder);
    position: absolute;
    left: 43px;
    top: 50%;
    transform: translateY(-50%);
    color: #999;
    pointer-events: none;
    z-index: 2;
    font-size: 14px;
}

/* 搜索框基础样式（容器也透明） */
.nj-chat-tab-search {
    border: none !important;
    box-shadow: none !important;
    margin-top: 100px !important;
    position: relative !important;
    z-index: 1 !important;
    background: transparent !important;   /* 容器背景也透明，确保整体透明 */
}

/* 当搜索框获得焦点时，隐藏自定义文案 */
.nj-chat-tab-search:focus-within::after {
    display: none !important;
}
/* ========== 强制恢复便签区域（搜索框下方，聊天列表上方） ========== */
.nj-chat-tab-notes {
    display: block !important;
    height: auto !important;
    overflow-x: auto !important;       /* 横向滚动保留 */
    overflow-y: visible !important;    /* 改为 visible，让阴影不被裁剪 */
    white-space: nowrap !important;
    margin: 12px 0 var(--notes-margin-bottom) 0 !important;
    padding: 0 16px !important;
    background: transparent !important;
    position: relative !important;
    z-index: 10 !important;            /* 提高层级，确保在列表上方 */
}

/* 便签内的原生子元素全部显示 */
.nj-chat-tab-notes > * {
    display: inline-block !important;
    visibility: visible !important;
}

/* 聊天列表正常排列在便签下方，且不覆盖便签阴影 */
.nj-chat-tab-list {
    position: relative !important;
    z-index: 1 !important;             /* 低于便签的层级 */
    margin-top: 0px !important;          /* 取消上边距，依靠便签的下边距 */
}

/* ========== 便签：只保留圆形头像（无阴影、无红心、无文字气泡） ========== */

/* 隐藏气泡对话内容 */
.nj-chat-tab-note-bubble {
    display: none !important;
}

/* 隐藏所有文本（名字、描述等） */
.nj-chat-tab-note-item .note-name,
.nj-chat-tab-note-item .note-text,
.nj-chat-tab-note-item .nj-chat-tab-note-name,
.nj-chat-tab-note-item .nj-chat-tab-note-text,
.nj-chat-tab-note-item > span:not(.nj-chat-tab-note-avatar):not(.nj-chat-tab-note-liked) {
    display: none !important;
}

/* 隐藏红心 */
.nj-chat-tab-note-liked {
    display: none !important;
}

/* ========== 便签区域整体向左移动 + 控制显示宽度 ========== */
.nj-chat-tab-notes {
    padding-left: var(--notes-padding-left) !important;   /* 向左移动，自调适配❤️❤️❤️ */
    width: 100% !important;
}

/* 头像间距调整 */
.nj-chat-tab-note-item {
    margin-right: var(--notes-item-margin-right) !important;
}

.nj-chat-tab-notes {
    padding-bottom: 5px !important;   /* 增加内边距，为阴影留出空间 */
}

/* ========== 统一便签头像垂直对齐（保留原有间距） ========== */
.nj-chat-tab-note-item {
    vertical-align: top !important;   /* 或 middle/bottom，统一即可 */
}
.nj-chat-tab-note-avatar {
    vertical-align: top !important;
}
/* 便签头像：圆形 + 无阴影 */
.nj-chat-tab-note-avatar,
.nj-chat-tab-note-avatar img,
.nj-chat-tab-note-avatar > div {
    border-radius: 50% !important;    /* 圆形 */
    box-shadow: none !important;      /* 移除所有阴影 */

    background-color: transparent !important;
}

/* 强制所有便签头像（包括 user 和 char）添加边框 */
.nj-chat-tab-note-avatar,
.nj-chat-tab-note-avatar img,
.nj-chat-item-user .nj-chat-tab-note-avatar,
.nj-chat-item-char .nj-chat-tab-note-avatar,
.nj-chat-item [class*="note-avatar"] {
    border: var(--note-avatar-border) !important;
    box-sizing: border-box !important;
}

/* 强制所有便签头像大小统一（解决 char/user 大小不一） */
.nj-chat-tab-note-avatar,
.nj-chat-tab-note-avatar img,
.nj-chat-tab-note-avatar > *,
.nj-chat-item-char .nj-chat-tab-note-avatar,
.nj-chat-item-user .nj-chat-tab-note-avatar {
    width: var(--note-avatar-size) !important;
    height: var(--note-avatar-size) !important;
    min-width: var(--note-avatar-size) !important;
    max-width: var(--note-avatar-size) !important;
    min-height: var(--note-avatar-size) !important;
    max-height: var(--note-avatar-size) !important;
    object-fit: cover !important;
    border-radius: 50% !important;      /* 保持与你之前的圆角一致 */
    box-sizing: border-box !important;  /* 避免内边距影响尺寸 */
}

/* 隐藏原有的“消息”标题 */
.nj-chat-tab-section-title {
    display: none !important;
}

/* ========== 置顶组和普通组各自独立圆角框（修复普通组下圆角） ========== */

/* 所有聊天项基础样式 */
.nj-chat-item {
    background: rgba(255, 255, 255, 0.85) !important;
    margin: 0 !important;
    border-radius: 0 !important;
    border: none !important;
    box-shadow: none !important;
    margin-left: 16px !important;
    margin-right: 16px !important;
}

/* ---------- 置顶组 ---------- */
/* 第一个置顶项（前无置顶项）上圆角 */
.nj-chat-item-pinned:not(.nj-chat-item-pinned + .nj-chat-item-pinned) {
    border-top-left-radius: 16px !important;
    border-top-right-radius: 16px !important;
}
/* 最后一个置顶项（后无置顶项）下圆角 + 底部间距 */
.nj-chat-item-pinned:not(:has(+ .nj-chat-item-pinned)) {
    border-bottom-left-radius: 16px !important;
    border-bottom-right-radius: 16px !important;
    margin-bottom: 20px !important;
}
/* 只有一个置顶项：全圆角 + 间距 */
.nj-chat-item-pinned:only-of-type {
    border-radius: 16px !important;
    margin-bottom: 20px !important;
}

/* ---------- 置顶与普通之间的衔接 ---------- */
.nj-chat-item-pinned + .nj-chat-item:not(.nj-chat-item-pinned) {
    margin-top: 20px !important;
    border-top-left-radius: 16px !important;
    border-top-right-radius: 16px !important;
}

/* ---------- 普通组（修复下圆角） ---------- */
/* 普通组第一个（前无普通项，且前面不是置顶的情况上面已处理，这里处理普通组自身的第一个） */
.nj-chat-item:not(.nj-chat-item-pinned):first-of-type {
    border-top-left-radius: 16px !important;
    border-top-right-radius: 16px !important;
}
/* 普通组最后一个：使用 :last-child 或 :last-of-type 双重保险 */
.nj-chat-item:not(.nj-chat-item-pinned):last-child,
.nj-chat-item:not(.nj-chat-item-pinned):last-of-type {
    border-bottom-left-radius: 16px !important;
    border-bottom-right-radius: 16px !important;
}
/* 只有一个普通项时：全圆角 */
.nj-chat-item:not(.nj-chat-item-pinned):only-child,
.nj-chat-item:not(.nj-chat-item-pinned):only-of-type {
    border-radius: 16px !important;
}

/* 清除组内相邻项的多余圆角 */
.nj-chat-item-pinned + .nj-chat-item-pinned {
    border-radius: 0 !important;
}
.nj-chat-item:not(.nj-chat-item-pinned) + .nj-chat-item:not(.nj-chat-item-pinned) {
    border-radius: 0 !important;
}

/* 强制修复普通组下圆角（放在 CSS 最末尾） */
.nj-chat-tab-list .nj-chat-item:not(.nj-chat-item-pinned):last-child {
    border-bottom-left-radius: 16px !important;
    border-bottom-right-radius: 16px !important;
}
/* 备用：使用兄弟选择器确保最后一个普通项 */
.nj-chat-item:not(.nj-chat-item-pinned):not(:has(+ .nj-chat-item:not(.nj-chat-item-pinned))) {
    border-bottom-left-radius: 16px !important;
    border-bottom-right-radius: 16px !important;
}

/* 如果希望装饰层也呈圆形（与头像一致），取消下面注释 */
/* .nj-chat-item-avatar::before {
    border-radius: inherit !important;
    overflow: hidden !important;
} */

/* ========== 未读角标在装饰图之上 ========== */
.nj-chat-item-unread-badge,
.nj-chat-item [class*="unread"],
.nj-chat-item [class*="badge"] {
    z-index: 15 !important;  /* 大于装饰层的 5 */
    position: absolute !important; /* 确保角标绝对定位 */
}

/* 未读角标颜色改为 #0F80E6（蓝色） */
.nj-chat-item-unread-badge,
.nj-chat-item [class*="unread"],
.nj-chat-item [class*="badge"],
.nj-chat-item [class*="Badge"] {
    background-color: #0F80E6 !important;
}

/* 底栏未读角标颜色改为 #0F80E6（蓝色） */
.nj-tab-bottom-total-unread,
.nj-tab-bottom-moments-dot {
    background-color: #0F80E6 !important;
}

/* ========== 置顶联系人：隐藏原生置顶标志，替换为自定义图床图片 ========== */

/* 1. 隐藏原生的置顶图标（各种可能的类名） */
.nj-chat-item-pinned [class*="pin"],
.nj-chat-item-pinned [class*="Pin"],
.nj-chat-item-pinned [class*="thumbtack"],
.nj-chat-item-pinned svg.pin-icon,
.nj-chat-item-pinned .pin-icon,
.nj-chat-item-pinned .nj-chat-item-pin {
    display: none !important;
}

/* 2. 在置顶项的右上角添加自定义图片 */
.nj-chat-item-pinned {
    position: relative !important;
}

.nj-chat-item-pinned::after {
    content: "" !important;
    background-image: var(--pin-icon) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;

    /* 定位到右上角，可自行调整 top / right / width / height */
    position: absolute !important;
    top: 45px !important;
    right: 20px !important;
    width: 13px !important;
    height: 13px !important;
    z-index: 15 !important;
    pointer-events: none !important;
}


/* 所有头像的统一装饰，（头像框❤️❤️❤️❤️❤️❤️） */
.nj-chat-item-avatar::before {
    content: "" !important;
    position: absolute !important;
    top: var(--chat-avatar-offset-top) !important;      /* 加大偏移，让装饰完全外扩 */
    left: var(--chat-avatar-offset-left) !important;
    width: calc(100% + var(--chat-avatar-size-increase)) !important;  /* 比容器大10px */
    height: calc(100% + var(--chat-avatar-size-increase)) !important;
    background-image: var(--avatar-decor) !important;
    background-size: cover !important;     /* 改为 cover 填满区域，不留白 */
    background-repeat: no-repeat !important;
    background-position: center !important;
    border-radius: 0 !important;           /* 关键：不继承圆角，避免裁剪 */
    pointer-events: none !important;
    z-index: 5 !important;
}

/* 调节聊天列表头像大小 */
.nj-chat-item-avatar {
    width: var(--chat-avatar-size) !important;
    height: var(--chat-avatar-size) !important;
    min-width: var(--chat-avatar-size) !important;
    min-height: var(--chat-avatar-size) !important;
}
/* ========== 普通组上方添加三个单词：Chats（带下划线），Friends Groups（灰色）❤️❤️❤️❤️❤️❤️ ========== */
.nj-chat-tab-list {
    position: relative !important;
    overflow: visible !important;
    margin-top: 50px !important;    /* 为文字预留空间 */
    text-align: center !important;  /* 辅助居中 */
}

/* 显示 "Chats" 并自带下划线 */
.nj-chat-tab-list::before {
    content: "Chats";
    display: inline-block;          /* 使宽度可设置 */
    width: 60px;                    /* 下划线宽度，可自行调整（例如 80px、90px） */
    text-align: center;             /* 文字水平居中 */
    position: absolute;
    top: -30px;
    left: var(--chats-left-offset);
    transform: translateX(-50%);
    white-space: nowrap;
    font-size: 15px;
    font-weight: 500;
    color: #000000;
    background: transparent;
    pointer-events: none;
    z-index: 100;
    border-bottom: 2px solid #000000;  /* 下划线会跟随宽度 */
    padding-bottom: 2px;
}

.nj-chat-tab-list::after {
    content: "Friends        Groups";      /* 中间的空格数量决定间距，可自行增减 */
    white-space: pre !important;       /* 关键：保留空格，不合并 */
    position: absolute;
    top: -30px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 15px;
    font-weight: 500;
    color: #6c6c70;
    background: transparent;
    pointer-events: none;
    z-index: 100;
    margin-left: var(--friends-groups-offset);                 /* 可能需要微调，因为文字总宽度变了 */
}

/* ========== 修复底栏悬浮胶囊下半部分无背景 ========== */
/* 1. 为聊天 tab 添加固定背景层（颜色可自行修改） */
#messaging-chat-tab::before {
    content: '' !important;
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    background-color: #f5f5f5 !important;  /* 改成你想要的底色，建议与底栏背景相似 */
    z-index: -1 !important;
    pointer-events: none !important;
}

/* 2. 底栏样式调整：取消 margin-bottom，改用 transform 或定位来实现悬浮感 */
.nj-tab-bottom-bar {
    background: rgba(265, 265, 265, 0.85) !important;
    backdrop-filter: blur(20px) !important;
    border-radius: 36px !important;
    margin: 0 36px !important;           /* 左右留白，底部不留边距 */
    margin-bottom: 25px !important;         /* 关键：取消底部外边距 */
    width: calc(80%) !important;
    padding: 8px 16px !important;
    padding-bottom: calc(-16px + var(--nuo-safe-bottom, 0px)) !important;
    border: none !important;
}

/* ========== 彻底清除便签头像上的所有加号、伪元素和多余标记 ========== */
/* 隐藏所有便签头像的伪元素（不论 before 还是 after） */
.nj-chat-tab-note-avatar::before,
.nj-chat-tab-note-avatar::after,
.nj-chat-tab-note-avatar > *::before,
.nj-chat-tab-note-avatar > *::after {
    content: none !important;
    display: none !important;
}

/* 隐藏任何绝对定位在便签头像上的加号（可能由其他类名产生） */
.nj-chat-tab-note-avatar [class*="add"],
.nj-chat-tab-note-avatar [class*="plus"],
.nj-chat-tab-note-avatar .plus-icon,
.nj-chat-tab-note-avatar .add-icon {
    display: none !important;
}

/* 如果加号是作为背景图或独立元素，直接隐藏整个便签内的额外标志 */
.nj-chat-tab-note-item .nj-chat-tab-note-liked,
.nj-chat-tab-note-item .note-add {
    display: none !important;
}

/* ========== 聊天名称前添加自定义图标 ========== */
/* 强制名称容器为块级/内联块，并留出左侧空间 */
.nj-chat-item-name {
    display: inline-block !important;
    padding-left: 55px !important;      /* 根据图标宽度调整，避免遮挡文字 */
    position: relative !important;
}

/* 普通组图标 */
.nj-chat-item:not(.nj-chat-item-pinned) .nj-chat-item-name::before {
    content: "" !important;
    position: absolute !important;
    left: 0px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    width: 50px !important;
    height: 28px !important;
    background-image: var(--name-before-ordinary) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
}

/* 置顶组图标 */
.nj-chat-item-pinned .nj-chat-item-name::before {
    content: "" !important;
    position: absolute !important;
    left: 0px !important;
    top: 45% !important;
    transform: translateY(-50%) !important;
    width: 50px !important;
    height: 28px !important;
    background-image: var(--name-before-pinned) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
}

/* 名称容器预留右侧空间 */
.nj-chat-item-name {
    position: relative !important;
    padding-right: 32px !important;   /* 根据最大图标宽度调整 */
}

/* 普通组：名称后图标（大小、位置、图床独立） */
.nj-chat-item:not(.nj-chat-item-pinned) .nj-chat-item-name::after {
    content: "" !important;
    position: absolute !important;
    right: 4px !important;          /* 水平偏移，可调 */
    top: 46% !important;
    transform: translateY(-50%) !important;
    width: 25px !important;         /* 普通组图标宽度 */
    height: 25px !important;        /* 普通组图标高度 */
    background-image: var(--name-after-ordinary) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
}

/* 置顶组：名称后图标（大小、位置、图床独立） */
.nj-chat-item-pinned .nj-chat-item-name::after {
    content: "" !important;
    position: absolute !important;
    right: 5px !important;          /* 可单独调整置顶组图标的水平位置 */
    top: 50% !important;
    transform: translateY(-50%) !important;
    width: 19px !important;         /* 置顶组图标宽度 */
    height: 19px !important;        /* 置顶组图标高度 */
    background-image: var(--name-after-pinned) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
}

/* ========== 夜间模式适配 ========== */
[data-color-scheme="dark"] {
    /* 主背景色 */
    --dark-bg: #1a1a1e;
    --dark-card: rgba(30, 30, 35, 0.9);
