}
[data-color-scheme="dark"] .nj-chat-item-name,
[data-color-scheme="dark"] .nj-chat-item-preview,
[data-color-scheme="dark"] .nj-chat-item-time {
    color: #e0e0e0 !important;
}
[data-color-scheme="dark"] .nj-chat-item-preview {
    color: #aaa !important;
}
[data-color-scheme="dark"] .nj-chat-item-time {
    color: #888 !important;
}

/* 名称前图床（普通组与置顶组）—— 保持原图，若原图深色需调整滤镜，这里不变 */
/* 名称后图标 —— 不变，由用户自备图床决定 */

/* 头像装饰层（不变） */

/* 便签头像边框颜色调亮一点 */
[data-color-scheme="dark"] .nj-chat-tab-note-avatar {
    border: 1.9px solid #888 !important;
}

/* 四张装饰图片的白色边框保留，不覆盖 */

/* 单词区域（Chats Friends Groups） */
[data-color-scheme="dark"] .nj-chat-tab-list::before {
    color: #e0e0e0 !important;
    border-bottom-color: #e0e0e0 !important;
}
[data-color-scheme="dark"] .nj-chat-tab-list::after {
    color: #aaa !important;
}

/* 底栏悬浮胶囊 */
[data-color-scheme="dark"] .nj-tab-bottom-bar {
    background: rgba(40, 40, 45, 0.85) !important;
    border: 1px solid rgba(255, 255, 255, 0.1) !important;
    box-shadow: 0 -2px 12px rgba(0, 0, 0, 0.2) !important;
}

/* 底栏文字和图标（通过滤镜反色或调整亮度） */
[data-color-scheme="dark"] .nj-tab-bottom-icon {
    filter: brightness(0) invert(1) !important;
    opacity: 0.8 !important;
}
[data-color-scheme="dark"] .nj-tab-bottom-item-active .nj-tab-bottom-icon {
    opacity: 1 !important;
}
[data-color-scheme="dark"] .nj-tab-bottom-item::after {
    color: #aaa !important;
}
[data-color-scheme="dark"] .nj-tab-bottom-item-active::after {
    color: #fff !important;
}

/* 底栏未读角标背景（已在日间设为蓝色，夜间保留蓝色，可微调） */
[data-color-scheme="dark"] .nj-tab-bottom-total-unread,
[data-color-scheme="dark"] .nj-tab-bottom-moments-dot {
    background-color: #0F80E6 !important; /* 保持蓝色，也可改为 #3b8fe6 */
}

/* 未读角标文字和背景（日间蓝色，夜间可稍亮） */
[data-color-scheme="dark"] .nj-chat-item-unread-badge,
[data-color-scheme="dark"] .nj-chat-item [class*="unread"],
[data-color-scheme="dark"] .nj-chat-item [class*="badge"] {
    background-color: #3b8fe6 !important;
}

/* 滚动条暗色 */
[data-color-scheme="dark"] ::-webkit-scrollbar {
    background-color: #1a1a1e;
}
[data-color-scheme="dark"] ::-webkit-scrollbar-thumb {
    background-color: #3a3a3e;
    border-radius: 10px;
}

[data-color-scheme="dark"] .nj-chat-item:not(.nj-chat-item-pinned) .nj-chat-item-name::after {
    background-image: var(--name-after-ordinary-dark) !important;
}

[data-color-scheme="dark"] .nj-chat-item-pinned .nj-chat-item-name::after {
    background-image: var(--name-after-pinned-dark) !important;
    width: 40px !important;   /* 改为您需要的大小 */
    height: 40px !important;
}
[data-color-scheme="dark"] .nj-chat-item-pinned .nj-chat-item-name::after {
    /* 调整 right 值：增大则图标向左移动，减小则向右移动 */
    right: -5px !important;
}

/* 夜间模式：顶栏字母颜色白色 + 右上角图标反白（如之前未写则加上） */
[data-color-scheme="dark"] .nj-chat-tab-header-back::before,
[data-color-scheme="dark"] .nj-chat-tab-header-title-btn::before,
[data-color-scheme="dark"] .nj-chat-tab-header-title-btn::after {
    color: #ffffff !important;
}
[data-color-scheme="dark"] .nj-chat-tab-header-edit {
    filter: brightness(0) invert(1) !important;
}

/* 水枝by忽略 — nuojiji messaging app theme */

:root {
    /* ----- 顶栏文字（直接改引号里的内容） ----- */
    --header-letter: "U";                /* 左侧字母 */
    --header-title: "ionok";            /* 中间标题 */
    --header-arrow: "▼";                /* 倒三角 */

    /* ----- 搜索框占位文案 ----- */
    --search-placeholder: "Shine like the stars";

    /* ----- 四张装饰图片（替换为你的图床链接） ----- */
    --decor-img-1: url("🌸🌸🌸🌸");
    --decor-img-2: url("🌸🌸🌸🌸");
    --decor-img-3: url("🌸🌸🌸🌸");
    --decor-img-4: url("🌸🌸🌸🌸");

    /* ----- 右上角头像 ----- */
    --header-avatar: url("https://i.postimg.cc/C131F4pD/Image-1783405966832-119.png");

    /* ----- 置顶标志小图 ----- */
    --pin-icon: url("https://i.postimg.cc/L4j4tLps/Image-1783405964912-426.png");

    /* ----- 聊天名称前图标（普通组 & 置顶组） ----- */
    --name-before-ordinary: url("https://i.postimg.cc/c4XShc5H/Image-1783405971071-888.png");
    --name-before-pinned:  url("https://i.postimg.cc/BnbGV1ds/Image-1783405968799-888.png");

    /* ----- 聊天名称后图标（普通组 & 置顶组） ----- */
    --name-after-ordinary: url("https://i.postimg.cc/rFhBxwKT/Image-1783405959170-426.png");
    --name-after-pinned:   url("https://i.postimg.cc/FsstYLs4/Image-1783405957037-272.png");

    /* ----- 夜间模式后图标（普通组 & 置顶组） ----- */
    --name-after-ordinary-dark: url("https://i.postimg.cc/KvYVGhQp/Image-1783405954530-656.png");
    --name-after-pinned-dark:   url("https://i.postimg.cc/zXfMzYpQ/Image-1783405952334-502.png");

    /* ----- 头像装饰图（聊天列表头像外框） ----- */
    --avatar-decor: url("https://i.postimg.cc/SsC4GFH9/2026-03-15-122930.png");

    /* ----- 聊天列表头像大小（单位px） ----- */
    --chat-avatar-size: 40px;

    /* ----- 头像装饰外扩偏移（负值外扩） ----- */
    --chat-avatar-offset-top: -5px;
    --chat-avatar-offset-left: -5px;
    --chat-avatar-size-increase: 10px;   /* 装饰图比头像大多少 */

    /* ----- 便签头像大小与边框 ----- */
    --note-avatar-size: 46px;
    --note-avatar-border: 1.9px solid #dddddd;

    /* ----- 便签区域整体控制 ----- */
    --notes-padding-left: 48px;          /* 整体左移 */
    --notes-margin-bottom: 30px;         /* 下边距 */
    --notes-item-margin-right: 25px;     /* 头像间距 */

    /* ----- 四张装饰图片的位置与大小 ----- */
    --decor-top-offset: 110px;           /* 整体垂直位置 */
    --decor-size: 78px;                  /* 图片大小（宽高） */
    --decor-left-1: 6%;                  /* 第1张水平位置 */
    --decor-left-2: 28%;
    --decor-left-3: 50%;
    --decor-left-4: 72%;

    /* ----- 聊天列表 "Chats / Friends Groups" 位置 ----- */
    --chats-left-offset: 27%;
    --friends-groups-offset: 40px;
}

/* ========================================================== */

/* 全局统一底色 #E5F4F0，清除边框、阴影 */
#messaging-chat-tab,
.nj-chat-tab-header,
.nj-tab-bottom-bar,
.nj-chat-tab-list,
.nj-chat-tab-search {
    background-color: #E5F4F0 !important;
    border: none !important;
    box-shadow: none !important;
}

/* 顶栏基础样式 */
.nj-chat-tab-header {
    position: relative !important;
    min-height: 90px !important;
    height: auto !important;
    padding-top: 10px !important;
}

/* 隐藏原生返回箭头 */
.nj-chat-tab-header-back svg,
.nj-chat-tab-header-back img {
    display: none !important;
}
/* 字母 U 样式 */
.nj-chat-tab-header-back::before {
    content: var(--header-letter) !important;
    font-size: 32px !important;
    font-weight: 500 !important;
    position: absolute !important;
    left: 19px !important;
    top: 37px !important;
}

/* ionok 文字区域 */
.nj-chat-tab-header-title-btn {
    position: absolute !important;
    left: 45px !important;
    top: 40px !important;
    transform: none !important;
    z-index: 10 !important;
    font-size: 20px !important;
    font-weight: 600 !important;
    color: inherit !important;
    cursor: pointer !important;
}
.nj-chat-tab-header-title-btn > * {
    display: none !important;
}
.nj-chat-tab-header-title-btn::before {
    content: var(--header-title) !important;
}
/* 独立倒三角 */
.nj-chat-tab-header-title-btn::after {
    content: var(--header-arrow) !important;
    font-size: 11px !important;
    font-weight: 900 !important;
    margin-left: 0px !important;
    color: inherit !important;
}
/* 修改顶栏自定义文字颜色为 #585858 */
.nj-chat-tab-header-back::before {
    color: #585858 !important;
}
.nj-chat-tab-header-title-btn::before {
    color: #585858 !important;
}
.nj-chat-tab-header-title-btn::after {
    color: #585858 !important;
}

/* 右上角头像按钮 */
.nj-chat-tab-header-edit {
    position: absolute !important;
    right: 22px !important;
    top: 47px !important;
    width: 20px !important;
    height: 20px !important;
    color: transparent !important;
    background-image: var(--header-avatar) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    border-radius: 50% !important;
    cursor: pointer !important;
    z-index: 10 !important;
}
.nj-chat-tab-header-edit svg,
.nj-chat-tab-header-edit img {
    display: none !important;
}

/* ========== 强制统一定位参考 ========== */
#messaging-chat-tab {
    position: relative !important;
    border: none !important;
    box-shadow: none !important;
}

/* 清除三个装饰容器的所有可能产生定位上下文的属性 */
.nj-chat-tab-decor-top,
.nj-chat-tab-notes,
.nj-chat-tab-decor-mid {
    position: static !important;
    transform: none !important;
    will-change: auto !important;
    display: block !important;
    height: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    background: transparent !important;
    overflow: visible !important;
}

/* 隐藏这些容器内的原生子元素 */
.nj-chat-tab-decor-top > *,
.nj-chat-tab-notes > *,
.nj-chat-tab-decor-mid > * {
    display: none !important;
}

/* ========== 所有图片相对于 #messaging-chat-tab 绝对定位 ========== */
.nj-chat-tab-decor-top::before,
.nj-chat-tab-decor-top::after,
.nj-chat-tab-decor-mid::before,
.nj-chat-tab-decor-mid::after {
    content: "" !important;
    position: absolute !important;
    top: var(--decor-top-offset) !important;
    width: var(--decor-size) !important;
    height: var(--decor-size) !important;
    border-radius: 8px !important;
    border: 1.7px solid #ffffff !important;
    box-shadow: 0 2px 12px rgba(0,0,0,0.15) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    transform: rotate(0deg) !important;
    z-index: 10 !important;
}

/* 四张图片水平位置及独立旋转 */
.nj-chat-tab-decor-top::before {
    left: var(--decor-left-1) !important;
    transform: rotate(-4deg) !important;
    background-image: var(--decor-img-1) !important;
}
.nj-chat-tab-decor-top::after {
    left: var(--decor-left-2) !important;
    transform: rotate(4deg) !important;
    background-image: var(--decor-img-2) !important;
}
.nj-chat-tab-decor-mid::before {
    left: var(--decor-left-3) !important;
    transform: rotate(-3deg) !important;
    background-image: var(--decor-img-3) !important;
}
.nj-chat-tab-decor-mid::after {
    left: var(--decor-left-4) !important;
    transform: rotate(4deg) !important;
    background-image: var(--decor-img-4) !important;
}

/* 确保 decor-mid 容器不干扰布局 */
.nj-chat-tab-decor-mid {
    display: block !important;
    height: 0 !important;
    overflow: visible !important;
    position: static !important;
}

/* 彻底隐藏原生占位符 */
.nj-chat-tab-search input::placeholder {
    visibility: hidden !important;
    opacity: 0 !important;
    color: transparent !important;
}

/* 隐藏输入文字与光标 + 输入框完全透明 */
.nj-chat-tab-search input {
    color: transparent !important;
    caret-color: transparent !important;
    background: transparent !important;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
}

/* 自定义展示文案 */
.nj-chat-tab-search::after {
    content: var(--search-placeholder);
    position: absolute;
    left: 43px;
    top: 50%;
    transform: translateY(-50%);
    color: #999;
    pointer-events: none;
    z-index: 2;
    font-size: 14px;
}

/* 搜索框基础样式（容器也透明） */
.nj-chat-tab-search {
    border: none !important;
    box-shadow: none !important;
    margin-top: 100px !important;
    position: relative !important;
    z-index: 1 !important;
    background: transparent !important;
}

/* 当搜索框获得焦点时，隐藏自定义文案 */
.nj-chat-tab-search:focus-within::after {
    display: none !important;
}

/* ========== 强制恢复便签区域 ========== */
.nj-chat-tab-notes {
    display: block !important;
    height: auto !important;
    overflow-x: auto !important;
    overflow-y: visible !important;
    white-space: nowrap !important;
    margin: 12px 0 var(--notes-margin-bottom) 0 !important;
    padding: 0 16px !important;
    background: transparent !important;
    position: relative !important;
    z-index: 10 !important;
}

/* 便签内的原生子元素全部显示 */
.nj-chat-tab-notes > * {
    display: inline-block !important;
    visibility: visible !important;
}

/* 聊天列表正常排列在便签下方 */
.nj-chat-tab-list {
    position: relative !important;
    z-index: 1 !important;
    margin-top: 0px !important;
}

/* ========== 便签：只保留圆形头像 ========== */
.nj-chat-tab-note-bubble {
    display: none !important;
}

/* 隐藏所有文本 */
.nj-chat-tab-note-item .note-name,
.nj-chat-tab-note-item .note-text,
.nj-chat-tab-note-item .nj-chat-tab-note-name,
.nj-chat-tab-note-item .nj-chat-tab-note-text,
.nj-chat-tab-note-item > span:not(.nj-chat-tab-note-avatar):not(.nj-chat-tab-note-liked) {
    display: none !important;
}

/* 隐藏红心 */
.nj-chat-tab-note-liked {
    display: none !important;
}

/* ========== 便签区域整体向左移动 ========== */
.nj-chat-tab-notes {
    padding-left: var(--notes-padding-left) !important;
    width: 100% !important;
}

/* 头像间距调整 */
.nj-chat-tab-note-item {
    margin-right: var(--notes-item-margin-right) !important;
}

.nj-chat-tab-notes {
    padding-bottom: 5px !important;
}

/* ========== 统一便签头像垂直对齐 ========== */
.nj-chat-tab-note-item {
    vertical-align: top !important;
}
.nj-chat-tab-note-avatar {
    vertical-align: top !important;
}

/* 便签头像：圆形 + 无阴影 */
.nj-chat-tab-note-avatar,
.nj-chat-tab-note-avatar img,
.nj-chat-tab-note-avatar > div {
    border-radius: 50% !important;
    box-shadow: none !important;
    background-color: transparent !important;
}

/* 强制所有便签头像添加边框 */
.nj-chat-tab-note-avatar,
.nj-chat-tab-note-avatar img,
.nj-chat-item-user .nj-chat-tab-note-avatar,
.nj-chat-item-char .nj-chat-tab-note-avatar,
.nj-chat-item [class*="note-avatar"] {
    border: var(--note-avatar-border) !important;
    box-sizing: border-box !important;
}

/* 强制所有便签头像大小统一 */
.nj-chat-tab-note-avatar,
.nj-chat-tab-note-avatar img,
.nj-chat-tab-note-avatar > *,
.nj-chat-item-char .nj-chat-tab-note-avatar,
.nj-chat-item-user .nj-chat-tab-note-avatar {
    width: var(--note-avatar-size) !important;
    height: var(--note-avatar-size) !important;
    min-width: var(--note-avatar-size) !important;
    max-width: var(--note-avatar-size) !important;
    min-height: var(--note-avatar-size) !important;
    max-height: var(--note-avatar-size) !important;
    object-fit: cover !important;
    border-radius: 50% !important;
    box-sizing: border-box !important;
}

/* 隐藏原有的"消息"标题 */
.nj-chat-tab-section-title {
    display: none !important;
}

/* ========== 置顶组和普通组各自独立圆角框 ========== */
.nj-chat-item {
    background: rgba(255, 255, 255, 0.85) !important;
    margin: 0 !important;
    border-radius: 0 !important;
    border: none !important;
    box-shadow: none !important;
    margin-left: 16px !important;
    margin-right: 16px !important;
}

/* ---------- 置顶组 ---------- */
.nj-chat-item-pinned:not(.nj-chat-item-pinned + .nj-chat-item-pinned) {
    border-top-left-radius: 16px !important;
    border-top-right-radius: 16px !important;
}
.nj-chat-item-pinned:not(:has(+ .nj-chat-item-pinned)) {
    border-bottom-left-radius: 16px !important;
    border-bottom-right-radius: 16px !important;
    margin-bottom: 20px !important;
}
.nj-chat-item-pinned:only-of-type {
    border-radius: 16px !important;
    margin-bottom: 20px !important;
}

/* ---------- 置顶与普通之间的衔接 ---------- */
.nj-chat-item-pinned + .nj-chat-item:not(.nj-chat-item-pinned) {
    margin-top: 20px !important;
    border-top-left-radius: 16px !important;
    border-top-right-radius: 16px !important;
}

/* ---------- 普通组 ---------- */
.nj-chat-item:not(.nj-chat-item-pinned):first-of-type {
    border-top-left-radius: 16px !important;
    border-top-right-radius: 16px !important;
}
.nj-chat-item:not(.nj-chat-item-pinned):last-child,
.nj-chat-item:not(.nj-chat-item-pinned):last-of-type {
    border-bottom-left-radius: 16px !important;
    border-bottom-right-radius: 16px !important;
}
