/*⁣⁠‍​‍​⁠​‌‌‌​‌‌⁠⁠‍​​⁠​⁠​⁠⁠‌‍​⁠‌​⁠⁠​⁠⁠‍‍⁠‌‌‌‍⁠​⁠​​‍​​​⁠⁠​​‍‍‍⁠⁠⁠​‌⁠⁣ 仿thread消息列表图标2.0_vicc — nuojiji messaging app theme */

/* ============================================================
   仿 threads 消息列表美化 · vc请勿二传
============================================================ */

#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab {
  --header-safe-top: max(24px, env(safe-area-inset-top, 0px));
}

/* ============================================================
   全局背景全覆盖：全变量重置 + 底层纯色大遮罩（浅色纯白 / 深色纯黑）
   ============================================================ */
html,
body,
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab {
  background: #ffffff !important;
  --nj-msg-bg: #ffffff !important;
  --nj-msg-card-bg: #ffffff !important;
  position: relative !important;
  padding-bottom: calc(64px + 18px + env(safe-area-inset-bottom, 0px)) !important;
}

/* 2. 额外铺一层铺满全屏的纯白大图，垫在最底层挡住所有原生色差*/
#messaging-chat-tab::before,
#messaging-moments-tab::before,
#messaging-profile-tab::before,
#messaging-favorites-tab::before {
  content: '' !important;
  position: fixed !important;
  inset: 0 !important;
  background: #ffffff !important;
  z-index: -999 !important;
  pointer-events: none !important;
}

/* 3. 深色模式：所有背景变量与底层遮罩自动切为纯黑 */
[data-color-scheme="dark"] html,
[data-color-scheme="dark"] body,
[data-color-scheme="dark"] #messaging-chat-tab,
[data-color-scheme="dark"] #messaging-moments-tab,
[data-color-scheme="dark"] #messaging-profile-tab,
[data-color-scheme="dark"] #messaging-favorites-tab {
  background: #000000 !important;
  --nj-msg-bg: #000000 !important;
  --nj-msg-card-bg: #000000 !important;
}

/* 深色模式 */
[data-color-scheme="dark"] #messaging-chat-tab::before,
[data-color-scheme="dark"] #messaging-moments-tab::before,
[data-color-scheme="dark"] #messaging-profile-tab::before,
[data-color-scheme="dark"] #messaging-favorites-tab::before {
  background: #000000 !important;
}

/* ============================================================
   一、顶部 Header
   ============================================================ */

.nj-chat-tab-header {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding: calc(14px + var(--header-safe-top)) 18px 6px !important;
  background: transparent !important;
  box-shadow: none !important;
  border-bottom: none !important;
}

.nj-chat-tab-header-back {
  position: relative !important;
  width: auto !important;
  min-width: 80px !important;
  color: transparent !important;
  background: none !important;
}
.nj-chat-tab-header-back svg,
.nj-chat-tab-header-back img {
  display: none !important;
}
.nj-chat-tab-header-back::before {
  content: '消息';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  color: #1a1a1a;
  font-size: 30px;
  font-weight: 800;
  white-space: nowrap;
}

.nj-chat-tab-header-title-btn {
  opacity: 0 !important;
  pointer-events: auto !important;
}

/* 1. 容器显式设置宽高与相对定位，防止伪元素塌陷 */
.nj-chat-tab-header-edit {
  position: relative !important;
  width: 24px !important;
  height: 24px !important;
  display: inline-block !important;
}

/* 2. 重置原本的系统图标/图片，只留下伪元素绘制的自定义图标 */
.nj-chat-tab-header-edit svg,
.nj-chat-tab-header-edit img {
  display: none !important;
}

/* 3. 自定义编辑图标层：绝对定位铺满容器，层级设为 1 */
.nj-chat-tab-header-edit::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  z-index: 1 !important;
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20d%3D%22M12%203H5a2%202%200%200%200-2%202v14a2%202%200%200%200%202%202h14a2%202%200%200%200%202-2v-7%22%20fill%3D%22none%22%20stroke%3D%22%231a1a1a%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22/%3E%3Cpath%20d%3D%22M18.375%202.625a1%201%200%200%201%203%203l-9.013%209.014a2%202%200%200%201-.853.505l-2.873.84a.5.5%200%200%201-.62-.62l.84-2.873a2%202%200%200%201%20.506-.852z%22%20fill%3D%22%231a1a1a%22/%3E%3C/svg%3E') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* 4. 未读消息角标：绝对定位悬浮在图标上方，层级设为 99 */

.nj-chat-tab-header-edit > *:not(svg):not(img) {
  /*  精准定位 */
  position: absolute !important;
  top: -4px !important;
  right: -4px !important;
  left: auto !important;
  z-index: 99 !important;

  /*  彻底清除原生干扰（防止被压扁、拉伸的核心） */
  transform: none !important;            /* 关键：彻底关掉 transform 缩放 */
  min-width: 0 !important;              /* 清除原生最小宽度限制 */
  min-height: 0 !important;             /* 清除原生最小高度限制 */
  padding: 0 !important;                /* 清除原生内边距 */
  margin: 0 !important;

  /*  外观尺寸（直接修改这里的数值） */
  width: 14px !important;               /* 角标宽 */
  height: 14px !important;              /* 角标高 */
  background: #ff3b30 !important;       /* 背景色 */
  border-radius: 50% !important;        /* 50%正圆 4px 方角 */
  border: 1.5px solid #ffffff !important; /* 数字越大描边越粗 */

  /*  内部文字居中 */
  display: flex !important; /* 改成none就不显示点了 */
  align-items: center !important;
  justify-content: center !important;
  color: #ffffff !important;            /* 文字颜色 */
  font-size: 9px !important;            /* 0＝无数字显示 */
  font-weight: Bold !important;
  line-height: 1 !important;
  box-sizing: border-box !important;
}


/* ============================================================
   二、搜索栏
   ============================================================ */

.nj-chat-tab-search {
  display: flex !important;
