/* 底栏：未读角标与朋友圈红点仅显示小点（完全保留原版参数） */
.nj-tab-bottom-total-unread,
.nj-tab-bottom-bar-total-unread-badge {
 font-size: 0 !important;             /* 隐藏里面的数字 */
  color: transparent !important;       /* 确保文字透明 */
  width: 6px !important;               /* 红点宽度 */
  height: 6px !important;              /* 红点高度 */
  min-width: 0 !important;             /* 清除最小宽度限制 */
  padding: 0 !important;               /* 清除内边距 */
  border-radius: 50% !important;       /* 正圆红点 */
  background-color:#ff3b30 !important;
  position: absolute !important;
  top: 8px !important;                 /* 红点上下位置 */
  right: 13px !important;                /* 红点左右位置 */
  z-index: 10 !important;
}

.nj-tab-bottom-moments-dot {
  font-size: 0 !important;             /* 隐藏里面的数字 */
  color: transparent !important;       /* 确保文字透明 */
  width: 6px !important;               /* 红点宽度 */
  height: 6px !important;              /* 红点高度 */
  min-width: 0 !important;             /* 清除最小宽度限制 */
  padding: 0 !important;               /* 清除内边距 */
  border-radius: 50% !important;       /* 正圆红点 */
  background-color:#ff3b30 !important;
  position: absolute !important;
  top: 8px !important;                 /* 红点上下位置 越大越下*/
  right: 13px !important;                /* 红点左右位置 越大越左*/
  z-index: 10 !important;
}

