  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20d%3D%22M4%2010.5L12%204L20%2010.5V19A1%201%200%200%201%2019%2020H15V14H9V20H5A1%201%200%200%201%204%2019V10.5Z%22%20fill%3D%22%231a1a1a%22/%3E%3C/svg%3E');
