/* 浅色模式颜色变量 */
:root,
[data-color-scheme="light"] {
  --tg-bg: #ffffff;
  --tg-surface: #f3f5f7;
  --tg-surface-2: #eef2f5;
  --tg-line: rgba(15, 23, 42, 0.05);
  --tg-text: #1c2733;
  --tg-muted: #8795a2;
  --tg-faint: #acb6bf;
  --tg-blue: #2aabee;
  --tg-blue-deep: #2496d1;
  --tg-blue-soft: #dff3ff;
  --tg-badge: #29a9e8;
  --tg-tabbar-bg: rgba(255, 255, 255, 0.96);
  --tg-tabbar-inactive: #8997a5;
  --tg-header-bg: rgba(255, 255, 255, 0.96);
  --tg-story-ring: rgba(42, 171, 238, 0.22);
  --tg-story-plus: #29a9e8;
  --tg-highlight: var(--tg-blue);
  --tg-decor-opacity: 0.16;
  --tg-flash-color: var(--tg-blue-soft);
}

/* 深色模式颜色变量 */
[data-color-scheme="dark"] {
  --tg-bg: #17212b;
  --tg-surface: #1f2a36;
  --tg-surface-2: #2b3a47;
  --tg-line: rgba(255, 255, 255, 0.08);
  --tg-text: #eef4fa;
  --tg-muted: #8fa0ae;
  --tg-faint: #70808d;
  --tg-blue: #58bdf6;
  --tg-blue-deep: #49afe8;
  --tg-blue-soft: rgba(88, 189, 246, 0.18);
  --tg-badge: #48b7f2;
  --tg-tabbar-bg: rgba(23, 33, 43, 0.94);
  --tg-tabbar-inactive: #7c8b98;
  --tg-header-bg: rgba(23, 33, 43, 0.94);
  --tg-story-ring: rgba(88, 189, 246, 0.28);
  --tg-story-plus: #52baf3;
  --tg-highlight: var(--tg-blue);
  --tg-decor-opacity: 0.16;
  --tg-flash-color: var(--tg-blue-soft);
}

/* 将主题变量应用到四个页面与底栏 */
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab,
.nj-tab-bottom-bar {
  --nj-msg-bg: var(--tg-bg);
  --nj-msg-chat-bg: var(--tg-bg);
  --nj-msg-text: var(--tg-text);
  --nj-msg-text-muted: var(--tg-muted);
  --nj-msg-text-time: var(--tg-faint);
  --nj-msg-accent: var(--tg-blue);
  --nj-msg-card-bg: transparent;
  --nj-msg-card-bg-pinned: transparent;
  --nj-msg-card-radius: 0px;
  --nj-msg-card-border: none;
  --nj-msg-card-padding: 0px;
  --nj-msg-card-gap: 0px;
  --nj-msg-avatar-radius: 50%;
  --nj-msg-avatar-shadow: none;
  --nj-msg-unread-bg: var(--tg-badge);
  --nj-msg-unread-color: #ffffff;
  --nj-msg-tabbar-bg: var(--tg-tabbar-bg);
  --nj-msg-tabbar-active: var(--tg-blue);
  --nj-msg-tabbar-inactive: var(--tg-tabbar-inactive);
  --nj-msg-tabbar-overlay: transparent;
  --nj-msg-tabbar-radius: 0;
  --nj-msg-tabbar-padding: 0 0 calc(6px + var(--nuo-safe-bottom, 0px)) 0;
  --nj-msg-tabbar-border: 1px solid var(--tg-line);
  --nj-msg-tabbar-shadow: none;
  --nj-msg-chat-search-bg: var(--tg-surface);
  --nj-msg-chat-search-radius: 18px;
  --nj-msg-chat-note-bubble-bg: transparent;
  --nj-msg-chat-note-bubble-color: var(--tg-text);
  --nj-msg-chat-section-title-color: var(--tg-muted);
  --nj-msg-chat-header-title-color: inherit;
  --nj-msg-card-transition: all 0.2s ease;
  --nj-msg-card-active-transform: scale(0.985);
  --nj-msg-card-hover-transform: none;
  --nj-msg-fade-in-duration: 0.18s;
  --nj-msg-font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
  --nj-msg-font-family-heading: "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
}

/* 聊天页面根背景 */
#messaging-chat-tab {
  position: relative !important;
  background: var(--tg-bg) !important;
  color: var(--tg-text) !important;
}

/* 修复聊天列表最底部的原生白缝 */
#messaging-chat-tab::after {
  content: "";
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  bottom: calc(-1 * (68px + var(--nuo-safe-bottom, 0px) / 2)) !important;
  height: calc(68px + var(--nuo-safe-bottom, 0px) / 2) !important;
  background: var(--tg-bg) !important;
  z-index: 0 !important;
  pointer-events: none !important;
}

/* 其他页面使用统一背景 */
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab {
  background: var(--tg-bg) !important;
  color: var(--tg-text) !important;
}

/* 聊天页顶部栏 */
.nj-chat-tab-header {
  position: sticky !important;
  top: 0 !important;
  z-index: 50 !important;
  min-height: 54px !important;
  padding: calc(10px + var(--nuo-safe-top, 0px)) 14px 8px 14px !important;
  background: var(--tg-header-bg) !important;
  backdrop-filter: blur(18px) !important;
  -webkit-backdrop-filter: blur(18px) !important;
  border-bottom: none !important;
  box-shadow: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
}

/* 顶部左侧 Telegram 标识 */
.nj-chat-tab-header-back {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  min-width: 70px !important;
  padding: 0 !important;
  margin: 0 !important;
  color: var(--tg-blue) !important;
  font-size: 0 !important;
  line-height: 1 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* 隐藏顶部左侧原图标 */
.nj-chat-tab-header-back::before {
  content: none !important;
  display: none !important;
}

/* 显示 Telegram 文字 */
.nj-chat-tab-header-back::after {
  content: "Telegram";
  display: inline-block;
  font-size: 22px;
  line-height: 1.1;
  font-weight: 700;
  color: var(--tg-blue);
}

/* 隐藏顶部左侧系统图标 */
.nj-chat-tab-header-back svg,
.nj-chat-tab-header-back i,
.nj-chat-tab-header-back .icon {
  display: none !important;
}

/* 顶部中间标题 */
.nj-chat-tab-header-title-btn {
  flex: 1 !important;
  text-align: center !important;
  color: var(--tg-text) !important;
  font-size: 18px !important;
  font-weight: 500 !important;
  letter-spacing: 0 !important;
}

/* 顶部右侧编辑按钮 */
.nj-chat-tab-header-edit {
  min-width: 70px !important;
  text-align: right !important;
  color: var(--tg-muted) !important;
  font-size: 18px !important;
}

/* 清理顶部栏额外伪元素 */
.nj-chat-tab-header::after,
.nj-chat-tab-header-title-btn::before,
.nj-chat-tab-header-title-btn::after {
  content: none !important;
  display: none !important;
}

/* 便签头像横向区域 */
.nj-chat-tab-notes {
  background: transparent !important;
  padding-top: 6px !important;
}

/* 单个便签项目 */
.nj-chat-tab-note-item {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* 便签圆形头像 */
.nj-chat-tab-note-avatar {
  position: relative !important;
  width: 54px !important;
  height: 54px !important;
  border-radius: 50% !important;
  overflow: visible !important;
  box-shadow: 0 0 0 2px var(--tg-bg), 0 0 0 4px var(--tg-story-ring) !important;
}

/* 便签头像图片 */
.nj-chat-tab-note-avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 50% !important;
}

/* 便签头像右下角加号 */
.nj-chat-tab-note-avatar::after {
  content: "+";
  position: absolute;
  right: -2px;
  bottom: -1px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--tg-story-plus);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
  box-shadow: 0 0 0 2px var(--tg-bg);
}

/* 便签文字气泡 */
.nj-chat-tab-note-bubble {
  background: transparent !important;
  color: var(--tg-muted) !important;
  font-size: 11px !important;
  padding: 0 !important;
}

/* 隐藏便签点赞图标 */
.nj-chat-tab-note-liked {
  display: none !important;
}

/* 搜索框外层间距 */
.nj-chat-tab-search-wrap {
  padding: 4px 14px 8px 14px !important;
  background: transparent !important;
}

/* 搜索框深色外观 */
.glass-search.nj-chat-tab-search,
.nj-chat-tab-search.glass-search {
  position: relative !important;
  height: 40px !important;
  min-height: 40px !important;
  padding: 0 14px !important;
  gap: 10px !important;
  border-radius: 20px !important;
  display: flex !important;
  align-items: center !important;
  box-sizing: border-box !important;
  background-color: #2b3240 !important;
  color: #b9c2cd !important;
  box-shadow: none !important;
  border: none !important;
}

/* 深色模式搜索框 */
[data-color-scheme="dark"] .glass-search.nj-chat-tab-search,
[data-color-scheme="dark"] .nj-chat-tab-search.glass-search {
  background-color: #2b3240 !important;
  color: #b9c2cd !important;
}

/* 浅色模式搜索框 */
[data-color-scheme="light"] .glass-search.nj-chat-tab-search,
[data-color-scheme="light"] .nj-chat-tab-search.glass-search {
  background-color: #f1f3f6 !important;
  color: #9aa4af !important;
}

/* 搜索图标 */
.glass-search.nj-chat-tab-search svg,
.nj-chat-tab-search.glass-search svg {
  width: 20px !important;
  height: 20px !important;
  min-width: 20px !important;
  flex: 0 0 20px !important;
  color: #b5bdc8 !important;
  stroke-width: 2.2 !important;
}

/* 浅色模式搜索图标 */
[data-color-scheme="light"] .glass-search.nj-chat-tab-search svg,
[data-color-scheme="light"] .nj-chat-tab-search.glass-search svg {
  color: #a0a9b4 !important;
}

/* 搜索输入框 */
.glass-search.nj-chat-tab-search input,
.nj-chat-tab-search.glass-search input {
  width: 100% !important;
  height: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  outline: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: #eef3f8 !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  line-height: 1 !important;
  caret-color: #7fc8f8 !important;
}

/* 浅色模式搜索输入文字 */
[data-color-scheme="light"] .glass-search.nj-chat-tab-search input,
[data-color-scheme="light"] .nj-chat-tab-search.glass-search input {
  color: #1f2937 !important;
}

/* 浅色模式搜索占位文字 */
[data-color-scheme="light"] .glass-search.nj-chat-tab-search input::placeholder,
[data-color-scheme="light"] .nj-chat-tab-search.glass-search input::placeholder {
  color: #9aa4af !important;
}

/* 清除搜索框聚焦阴影 */
.glass-search.nj-chat-tab-search input:focus,
.nj-chat-tab-search.glass-search input:focus {
  outline: none !important;
  box-shadow: none !important;
}

/* 小屏幕搜索框尺寸 */
@media (max-width: 600px) {
  .nj-chat-tab-search-wrap {
    padding: 4px 12px 6px 12px !important;
  }

  .glass-search.nj-chat-tab-search,
  .nj-chat-tab-search.glass-search {
    height: 38px !important;
    min-height: 38px !important;
    padding: 0 12px !important;
    border-radius: 19px !important;
  }
}

/* 彻底隐藏原生占位文字 */
.nj-chat-tab-search input::placeholder {
  font-size: 0 !important;
  opacity: 0 !important;
  color: transparent !important;
  text-indent: -9999px !important;
}

/* 自定义占位文字,内容可以自己改 */
.nj-chat-tab-search {
  position: relative !important;
}

.nj-chat-tab-search::after {
  content: "Search Chats";
  position: absolute;
  left: 44px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 15px;
  font-weight: 500;
  color: #c3ccd7;
  font-family: inherit;
  pointer-events: none;
  white-space: nowrap;
  z-index: 1;
  opacity: 1;
  transition: opacity 0.15s;
}

/* 浅色模式占位文字颜色 */
[data-color-scheme="light"] .nj-chat-tab-search::after {
  color: #9aa4af;
}

/* 输入框聚焦时隐藏自定义占位文字 */
.nj-chat-tab-search:focus-within::after {
  opacity: 0;
}

/* 输入框已经有内容时也隐藏自定义占位文字 */
.nj-chat-tab-search:has(input:not(:placeholder-shown))::after {
  opacity: 0;
}

/* 聊天分类标题容器 */
.nj-chat-tab-section-title {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  padding: 0 14px 10px 14px !important;
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  overflow: hidden !important;
}

/* 隐藏原始分类标题内容 */
.nj-chat-tab-section-title > * {
  display: none !important;
}

/* 自定义聊天分类标签 */
.nj-chat-tab-section-title::before {
  content: "所有聊天 5" !important;  /*可自定义 */
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: 28px !important;
  padding: 0 12px !important;
  border-radius: 999px !important;
  background: var(--tg-blue-soft) !important;
  color: var(--tg-blue-deep) !important;
  font-size: 12px !important;
  line-height: 1 !important;
  font-weight: 700 !important;
}

/* 清理分类标题额外伪元素 */
.nj-chat-tab-section-title::after {
  content: none !important;
  display: none !important;
}

/* 聊天列表容器需要定位基准，用来放绝对定位的说明文字和关闭按钮 */
.nj-chat-tab-list {
  position: relative !important;
}

/* 生日提示卡片标题，纯白背景与轻微悬浮阴影 */
.nj-chat-tab-list::before {
  content: "Add your birthday! 🎂";  /* 可自定义 /
  display: block;
  margin: 0 14px 8px 14px;
  padding: 9px 16px 25px 16px;
  border-radius: 23px;
  background: #ffffff;
  border: none;
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.05),
    0 3px 10px rgba(15, 23, 42, 0.04);
  color: #1c2733;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.15;
}

/* 生日提示卡片第二行说明文字 */
.nj-chat-tab-list::after {
  content: "Let your contacts know when you're celebrating";  /* 可自定义 */
  position: absolute;
  top: 28px;
  left: 30px;
  right: 28px;
  color: #8795a2;
  font-size: 11px;
  font-weight: 400;
  line-height: 1.15;
  pointer-events: none;
}

/* 深色模式生日提示卡片 */
[data-color-scheme="dark"] .nj-chat-tab-list::before {
  background: #1f2a36;
  box-shadow:
    0 1px 2px rgba(0, 0, 0, 0.20),
    0 3px 10px rgba(0, 0, 0, 0.16);
  color: #eef4fa;
}

[data-color-scheme="dark"] .nj-chat-tab-list::after {
  color: #8fa0ae;
}

/* 聊天列表容器 */
.nj-chat-tab-list {
  padding: 0 0 calc(82px + var(--nuo-safe-bottom, 0px)) 0 !important;
  background: var(--tg-bg) !important;
}

/* 单条聊天项目 */
.nj-chat-item {
  position: relative !important;
  display: flex !important;
  align-items: flex-start !important;
  gap: 12px !important;
  margin: 0 !important;
  padding: 10px 14px !important;
  background: var(--tg-bg) !important;
  border: none !important;
  border-bottom: 1px solid var(--tg-line) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* 聊天项目按压或悬浮背景 */
.nj-chat-item:hover {
  background: color-mix(in srgb, var(--tg-surface) 42%, transparent) !important;
}

/* 聊天头像容器 */
.nj-chat-item-avatar {
  position: relative !important;
  z-index: 1 !important;
  width: 52px !important;
  height: 52px !important;
  min-width: 52px !important;
  border-radius: 50% !important;
  overflow: visible !important;
  background: var(--tg-surface-2) !important;
}

/* 聊天头像图片 */
.nj-chat-item-avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 50% !important;
}

/* 聊天名称保持在头像背景装饰上方 */
.nj-chat-item-name {
  position: relative !important;
  z-index: 1 !important;
}

/* 聊天预览文字保持在头像背景装饰上方 */
.nj-chat-item-preview {
  position: relative !important;
  z-index: 1 !important;
}

/* 时间与图钉保持在名称同一行 */
.nj-chat-item-time {
  position: static !important;
  z-index: 1 !important;
  margin-left: auto !important;
  flex-shrink: 0 !important;
  background: rgba(140, 150, 160, 0.12) !important;
  color: #8895a1 !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  line-height: 1 !important;
  padding: 4px 8px !important;
  border-radius: 12px !important;
}

/* 深色模式时间胶囊 */
[data-color-scheme="dark"] .nj-chat-item-time {
  background: rgba(255, 255, 255, 0.12) !important;
  color: #a0b0c0 !important;
}

/* 未读徽标固定在头像右下角 */
.nj-chat-item-unread-badge {
  position: absolute !important;
  right: -4px !important;
  bottom: -4px !important;
  top: auto !important;
  min-width: 22px !important;
  height: 22px !important;
  padding: 0 6px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  border-radius: 999px !important;
  background: var(--tg-badge) !important;
  color: #fff !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  box-shadow: 0 0 0 2px #fff !important;
  z-index: 2 !important;
}

/* 深色模式未读徽标描边 */
[data-color-scheme="dark"] .nj-chat-item-unread-badge {
  box-shadow: 0 0 0 2px var(--tg-bg) !important;
}

/* 移除系统置顶图标 */
.nj-chat-item-pinned::before {
  content: none !important;
  display: none !important;
}

/* 置顶聊天的时间胶囊布局 */
.nj-chat-item-pinned .nj-chat-item-time {
  display: inline-flex !important;
  align-items: center !important;
  gap: 4px !important;
  padding: 4px 8px 4px 6px !important;
}

/* 置顶聊天的图钉 */
.nj-chat-item-pinned .nj-chat-item-time::before {
  content: "📌"; /*可自定义 */
  font-size: 13px !important;
  line-height: 1 !important;
  filter: grayscale(100%) opacity(0.6); /* 可删：想让图钉恢复彩色，删除这一行 */
}

/* 隐藏置顶聊天时间内的系统图标 */
.nj-chat-item-pinned .nj-chat-item-time > * {
  display: none !important;
}

/* 头像模糊背景装饰 */
.nj-chat-item {
  --nj-item-deco-1-image: var(--nj-item-avatar-url);
  --nj-item-deco-1-top: 0;
  --nj-item-deco-1-left: 0;
  --nj-item-deco-1-width: 100%;
  --nj-item-deco-1-height: 100%;
  --nj-item-deco-1-size: cover;
  --nj-item-deco-1-filter: blur(18px) saturate(1.3);
  --nj-item-deco-1-opacity: var(--tg-decor-opacity);
  --nj-item-deco-1-z: 0;
}

/* 有未读徽标的聊天左侧显示蓝色提示线 */
.nj-chat-item:has(.nj-chat-item-unread-badge) {
  box-shadow: inset 3px 0 0 var(--tg-highlight) !important;
}

/* 免打扰聊天变淡 */
.nj-chat-item[data-muted="true"] {
  opacity: 0.55;
}

/* 刚收到新消息时使用蓝色闪烁 */
@keyframes nj-item-flash-tg {
  0% {
    background: var(--tg-flash-color);
  }

  100% {
    background: transparent;
  }
}

/* 新消息闪烁效果 */
.nj-chat-item[data-flash="true"] {
  animation: nj-item-flash-tg 1.2s ease-out;
}

/* 角色生成回复时头像轻微呼吸 */
.nj-chat-item[data-generating="true"] .nj-chat-item-avatar {
  animation: nj-breathe 2s ease-in-out infinite;
}

/* 切换进入聊天页面时列表错落淡入 */
[data-tab-anim="enter"][data-active-tab="chat"] .nj-chat-item {
  animation: nj-item-fade-up 0.3s both;
  animation-delay: calc(min(var(--nj-item-index, 0), 6) * 25ms);
}

/* 朋友圈评论与点赞容器 */
.nj-moments-engagement {
  background: var(--tg-surface) !important;
  border: 1px solid var(--tg-line) !important;
  border-radius: 12px !important;
  padding: 8px 12px !important;
}

/* 朋友圈点赞文字 */
.nj-moments-likes {
  color: var(--tg-text) !important;
}

/* 朋友圈单条评论 */
.nj-moments-comment {
  color: var(--tg-text) !important;
}

/* 朋友圈评论作者名称 */
.nj-moments-comment-author {
  color: var(--tg-blue) !important;
  font-weight: 700 !important;
}

/* 朋友圈评论正文 */
.nj-moments-comment-content {
  color: var(--tg-text) !important;
}

/* 切换进入朋友圈时内容上滑淡入 */
[data-tab-anim="enter"][data-active-tab="moments"] .nj-moments-feed {
  animation: nj-tab-slide-up 0.35s both;
}

/* 悬浮底栏本体 */
.nj-tab-bottom-bar {
  position: fixed !important;
  left: 20px !important;
  right: 20px !important;
  bottom: calc(12px + var(--nuo-safe-bottom, 0px)) !important;
  transform: none !important;
  z-index: 80 !important;
  width: auto !important;
  max-width: 320px !important;
  margin: 0 auto !important;
  height: 60px !important;
  min-height: 0 !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: stretch !important;
  justify-content: space-between !important;
  padding: 6px !important;
  border-radius: 999px !important;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.08), 0 1px 3px rgba(0, 0, 0, 0.05) !important;
  backdrop-filter: blur(18px) !important;
  -webkit-backdrop-filter: blur(18px) !important;
  overflow: visible !important;
}

/* 浅色模式底栏 */
[data-color-scheme="light"] .nj-tab-bottom-bar {
  background: rgba(255, 255, 255, 0.96) !important;
  border: 1px solid rgba(0, 0, 0, 0.06) !important;
}

/* 深色模式底栏 */
[data-color-scheme="dark"] .nj-tab-bottom-bar {
  background: rgba(23, 33, 43, 0.94) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.3) !important;
}

/* 移除底栏额外伪元素 */
.nj-tab-bottom-bar::before,
.nj-tab-bottom-bar::after {
  display: none !important;
}

/* 底栏单个页面按钮 */
.nj-tab-bottom-item {
  position: relative !important;
  flex: 1 1 0% !important;
  height: 100% !important;
  min-height: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 3px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 999px !important;
  background: transparent !important;
  transform: none !important;
  box-shadow: none !important;
  font-size: 0 !important;
}

/* 浅色模式未选中底栏按钮 */
[data-color-scheme="light"] .nj-tab-bottom-item:not(.nj-tab-bottom-item-active) {
  color: #556270 !important;
}

/* 深色模式未选中底栏按钮 */
[data-color-scheme="dark"] .nj-tab-bottom-item:not(.nj-tab-bottom-item-active) {
  color: #8fa0ae !important;
}

/* 底栏图标 */
.nj-tab-bottom-icon {
  width: 22px !important;
  height: 22px !important;
  margin: 0 !important;
  font-size: 22px !important;
  line-height: 1 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  color: currentColor !important;
}

/* 隐藏系统底栏文字 */
.nj-tab-bottom-item span:not(.nj-tab-bottom-total-unread),
.nj-tab-bottom-item-label {
  display: none !important;
}

/* 自定义底栏文字样式 */
.nj-tab-bottom-item::after {
  display: block !important;
  font-size: 11px !important;
  line-height: 1 !important;
  font-weight: 700 !important;
  color: currentColor !important;
  white-space: nowrap !important;
}

/* 自定义聊天底栏文字 */
.nj-tab-bottom-item-chat::after {
  content: "Chat" !important; /* 可自定义 */
}

/* 自定义动态底栏文字 */
.nj-tab-bottom-item-moments::after {
  content: "dynamic" !important; /* 可自定义 */
}

/* 自定义收藏底栏文字 */
.nj-tab-bottom-item-favorites::after {
  content: "Collect" !important; /* 可自定义 */
}

/* 自定义个人资料底栏文字 */
.nj-tab-bottom-item-profile::after {
  content: "Profile" !important; /* 可自定义 */
}

/* 浅色模式当前底栏按钮 */
[data-color-scheme="light"] .nj-tab-bottom-item-active {
  background: linear-gradient(180deg, #dff0ff 0%, #d5ebff 100%) !important;
  color: #139fe8 !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 1px 2px rgba(19, 159, 232, 0.08) !important;
}

/* 深色模式当前底栏按钮 */
[data-color-scheme="dark"] .nj-tab-bottom-item-active {
  background: linear-gradient(180deg, #2b4b6e 0%, #1f3a55 100%) !important;
  color: #58bdf6 !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.15), 0 1px 2px rgba(0, 0, 0, 0.3) !important;
}

/* 底栏未读数字 */
.nj-tab-bottom-total-unread {
  position: absolute !important;
  top: 4px !important;
  right: calc(50% - 24px) !important;
  min-width: 18px !important;
  height: 18px !important;
  padding: 0 5px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  border-radius: 999px !important;
  background: #4fb8f2 !important;
  color: #fff !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  line-height: 1 !important;
  box-shadow: 0 2px 4px rgba(79, 184, 242, 0.3) !important;
  z-index: 3 !important;
}

/* 隐藏动态底栏红点 */
.nj-tab-bottom-moments-dot {
  display: none !important;
}

/* 系统开启减少动画时关闭全部自定义动画 */
@media (prefers-reduced-motion: reduce) {
  #messaging-chat-tab,
  #messaging-moments-tab,
  #messaging-profile-tab,
  #messaging-favorites-tab,
  .nj-tab-bottom-bar {
    --nj-msg-card-transition: none;
    --nj-msg-card-active-transform: none;
    --nj-msg-card-hover-transform: none;
    --nj-msg-tabbar-active-transform: none;
    --nj-msg-fade-in-duration: 0s;
  }

  .nj-chat-item,
  .nj-chat-item[data-flash="true"],
  .nj-chat-item[data-generating="true"] .nj-chat-item-avatar,
  .nj-moments-feed {
    animation: none !important;
    animation-delay: 0s !important;
    transition: none !important;
  }
}

/*⁣⁠‍​‍​⁠​‌‌‌​‌‌⁠⁠‍​​⁠​⁠​⁠⁠‌‍​⁠‌​⁠⁠​⁠⁠‍‍⁠‌‌‌‍⁠​⁠​​‍​​​⁠⁠​​‍‍‍⁠⁠⁠​‌⁠⁣ 仿 Telegram 消息主页主题 */

/* 浅色模式颜色变量 */
:root,
[data-color-scheme="light"] {
  --tg-bg: #ffffff;
  --tg-surface: #f3f5f7;
  --tg-surface-2: #eef2f5;
  --tg-line: rgba(15, 23, 42, 0.05);
  --tg-text: #1c2733;
  --tg-muted: #8795a2;
  --tg-faint: #acb6bf;
  --tg-blue: #2aabee;
  --tg-blue-deep: #2496d1;
  --tg-blue-soft: #dff3ff;
  --tg-badge: #29a9e8;
  --tg-tabbar-bg: rgba(255, 255, 255, 0.96);
  --tg-tabbar-inactive: #8997a5;
  --tg-header-bg: rgba(255, 255, 255, 0.96);
  --tg-story-ring: rgba(42, 171, 238, 0.22);
  --tg-story-plus: #29a9e8;
  --tg-highlight: var(--tg-blue);
  --tg-decor-opacity: 0.16;
  --tg-flash-color: var(--tg-blue-soft);
}

/* 深色模式颜色变量 */
[data-color-scheme="dark"] {
  --tg-bg: #17212b;
  --tg-surface: #1f2a36;
  --tg-surface-2: #2b3a47;
  --tg-line: rgba(255, 255, 255, 0.08);
  --tg-text: #eef4fa;
  --tg-muted: #8fa0ae;
  --tg-faint: #70808d;
  --tg-blue: #58bdf6;
  --tg-blue-deep: #49afe8;
  --tg-blue-soft: rgba(88, 189, 246, 0.18);
  --tg-badge: #48b7f2;
  --tg-tabbar-bg: rgba(23, 33, 43, 0.94);
  --tg-tabbar-inactive: #7c8b98;
  --tg-header-bg: rgba(23, 33, 43, 0.94);
  --tg-story-ring: rgba(88, 189, 246, 0.28);
  --tg-story-plus: #52baf3;
  --tg-highlight: var(--tg-blue);
  --tg-decor-opacity: 0.16;
  --tg-flash-color: var(--tg-blue-soft);
}

/* 将主题变量应用到四个页面与底栏 */
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab,
.nj-tab-bottom-bar {
  --nj-msg-bg: var(--tg-bg);
  --nj-msg-chat-bg: var(--tg-bg);
  --nj-msg-text: var(--tg-text);
  --nj-msg-text-muted: var(--tg-muted);
  --nj-msg-text-time: var(--tg-faint);
  --nj-msg-accent: var(--tg-blue);
  --nj-msg-card-bg: transparent;
  --nj-msg-card-bg-pinned: transparent;
  --nj-msg-card-radius: 0px;
  --nj-msg-card-border: none;
  --nj-msg-card-padding: 0px;
  --nj-msg-card-gap: 0px;
  --nj-msg-avatar-radius: 50%;
  --nj-msg-avatar-shadow: none;
  --nj-msg-unread-bg: var(--tg-badge);
  --nj-msg-unread-color: #ffffff;
  --nj-msg-tabbar-bg: var(--tg-tabbar-bg);
  --nj-msg-tabbar-active: var(--tg-blue);
  --nj-msg-tabbar-inactive: var(--tg-tabbar-inactive);
  --nj-msg-tabbar-overlay: transparent;
  --nj-msg-tabbar-radius: 0;
  --nj-msg-tabbar-padding: 0 0 calc(6px + var(--nuo-safe-bottom, 0px)) 0;
  --nj-msg-tabbar-border: 1px solid var(--tg-line);
  --nj-msg-tabbar-shadow: none;
  --nj-msg-chat-search-bg: var(--tg-surface);
  --nj-msg-chat-search-radius: 18px;
  --nj-msg-chat-note-bubble-bg: transparent;
  --nj-msg-chat-note-bubble-color: var(--tg-text);
  --nj-msg-chat-section-title-color: var(--tg-muted);
  --nj-msg-chat-header-title-color: inherit;
  --nj-msg-card-transition: all 0.2s ease;
  --nj-msg-card-active-transform: scale(0.985);
  --nj-msg-card-hover-transform: none;
  --nj-msg-fade-in-duration: 0.18s;
  --nj-msg-font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
  --nj-msg-font-family-heading: "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
}

/* 聊天页面根背景 */
#messaging-chat-tab {
  position: relative !important;
  background: var(--tg-bg) !important;
  color: var(--tg-text) !important;
}

/* 修复聊天列表最底部的原生白缝 */
#messaging-chat-tab::after {
  content: "";
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  bottom: calc(-1 * (68px + var(--nuo-safe-bottom, 0px) / 2)) !important;
  height: calc(68px + var(--nuo-safe-bottom, 0px) / 2) !important;
  background: var(--tg-bg) !important;
  z-index: 0 !important;
  pointer-events: none !important;
}

/* 其他页面使用统一背景 */
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab {
  background: var(--tg-bg) !important;
  color: var(--tg-text) !important;
}

/* 聊天页顶部栏 */
.nj-chat-tab-header {
  position: sticky !important;
  top: 0 !important;
  z-index: 50 !important;
  min-height: 54px !important;
  padding: calc(10px + var(--nuo-safe-top, 0px)) 14px 8px 14px !important;
  background: var(--tg-header-bg) !important;
  backdrop-filter: blur(18px) !important;
  -webkit-backdrop-filter: blur(18px) !important;
  border-bottom: none !important;
  box-shadow: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
}

/* 顶部左侧 Telegram 标识 */
.nj-chat-tab-header-back {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  min-width: 70px !important;
  padding: 0 !important;
  margin: 0 !important;
  color: var(--tg-blue) !important;
  font-size: 0 !important;
  line-height: 1 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* 隐藏顶部左侧原图标 */
.nj-chat-tab-header-back::before {
  content: none !important;
  display: none !important;
}

/* 显示 Telegram 文字 */
.nj-chat-tab-header-back::after {
  content: "Telegram";
  display: inline-block;
  font-size: 22px;
  line-height: 1.1;
  font-weight: 700;
  color: var(--tg-blue);
}

/* 隐藏顶部左侧系统图标 */
.nj-chat-tab-header-back svg,
.nj-chat-tab-header-back i,
.nj-chat-tab-header-back .icon {
  display: none !important;
}

/* 顶部中间标题 */
.nj-chat-tab-header-title-btn {
  flex: 1 !important;
  text-align: center !important;
  color: var(--tg-text) !important;
  font-size: 18px !important;
  font-weight: 500 !important;
  letter-spacing: 0 !important;
}

/* 顶部右侧编辑按钮 */
.nj-chat-tab-header-edit {
  min-width: 70px !important;
  text-align: right !important;
  color: var(--tg-muted) !important;
  font-size: 18px !important;
}

/* 清理顶部栏额外伪元素 */
.nj-chat-tab-header::after,
.nj-chat-tab-header-title-btn::before,
.nj-chat-tab-header-title-btn::after {
  content: none !important;
  display: none !important;
}

/* 便签头像横向区域 */
.nj-chat-tab-notes {
  background: transparent !important;
  padding-top: 6px !important;
}

/* 单个便签项目 */
.nj-chat-tab-note-item {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* 便签圆形头像 */
.nj-chat-tab-note-avatar {
  position: relative !important;
  width: 54px !important;
  height: 54px !important;
  border-radius: 50% !important;
  overflow: visible !important;
  box-shadow: 0 0 0 2px var(--tg-bg), 0 0 0 4px var(--tg-story-ring) !important;
}

/* 便签头像图片 */
.nj-chat-tab-note-avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 50% !important;
}

/* 便签头像右下角加号 */
.nj-chat-tab-note-avatar::after {
  content: "+";
  position: absolute;
  right: -2px;
  bottom: -1px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--tg-story-plus);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
  box-shadow: 0 0 0 2px var(--tg-bg);
}

/* 便签文字气泡 */
.nj-chat-tab-note-bubble {
  background: transparent !important;
  color: var(--tg-muted) !important;
  font-size: 11px !important;
  padding: 0 !important;
}

/* 隐藏便签点赞图标 */
.nj-chat-tab-note-liked {
  display: none !important;
}

/* 搜索框外层间距 */
.nj-chat-tab-search-wrap {
  padding: 4px 14px 8px 14px !important;
  background: transparent !important;
}

/* 搜索框深色外观 */
.glass-search.nj-chat-tab-search,
.nj-chat-tab-search.glass-search {
  height: 40px !important;
  min-height: 40px !important;
  padding: 0 14px !important;
  gap: 10px !important;
  border-radius: 20px !important;
  display: flex !important;
  align-items: center !important;
  box-sizing: border-box !important;
  background-color: #2b3240 !important;
  color: #b9c2cd !important;
  box-shadow: none !important;
  border: none !important;
}

/* 深色模式搜索框 */
[data-color-scheme="dark"] .glass-search.nj-chat-tab-search,
[data-color-scheme="dark"] .nj-chat-tab-search.glass-search {
  background-color: #2b3240 !important;
  color: #b9c2cd !important;
}

/* 浅色模式搜索框 */
[data-color-scheme="light"] .glass-search.nj-chat-tab-search,
[data-color-scheme="light"] .nj-chat-tab-search.glass-search {
  background-color: #f1f3f6 !important;
  color: #9aa4af !important;
}

/* 搜索图标 */
.glass-search.nj-chat-tab-search svg,
.nj-chat-tab-search.glass-search svg {
  width: 20px !important;
  height: 20px !important;
  min-width: 20px !important;
  flex: 0 0 20px !important;
  color: #b5bdc8 !important;
  stroke-width: 2.2 !important;
}

/* 浅色模式搜索图标 */
[data-color-scheme="light"] .glass-search.nj-chat-tab-search svg,
[data-color-scheme="light"] .nj-chat-tab-search.glass-search svg {
  color: #a0a9b4 !important;
}

/* 搜索输入框 */
.glass-search.nj-chat-tab-search input,
.nj-chat-tab-search.glass-search input {
  width: 100% !important;
  height: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  outline: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: #eef3f8 !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  line-height: 1 !important;
  caret-color: #7fc8f8 !important;
}

/* 搜索框占位文字 */
.glass-search.nj-chat-tab-search input::placeholder,
.nj-chat-tab-search.glass-search input::placeholder {
  color: #c3ccd7 !important;
  opacity: 1 !important;
  font-size: 15px !important;
  font-weight: 500 !important;
}

/* 浅色模式搜索输入文字 */
[data-color-scheme="light"] .glass-search.nj-chat-tab-search input,
[data-color-scheme="light"] .nj-chat-tab-search.glass-search input {
  color: #1f2937 !important;
}

/* 浅色模式搜索占位文字 */
[data-color-scheme="light"] .glass-search.nj-chat-tab-search input::placeholder,
[data-color-scheme="light"] .nj-chat-tab-search.glass-search input::placeholder {
  color: #9aa4af !important;
}

/* 清除搜索框聚焦阴影 */
.glass-search.nj-chat-tab-search input:focus,
.nj-chat-tab-search.glass-search input:focus {
  outline: none !important;
  box-shadow: none !important;
}

/* 小屏幕搜索框尺寸 */
@media (max-width: 600px) {
  .nj-chat-tab-search-wrap {
    padding: 4px 12px 6px 12px !important;
  }

  .glass-search.nj-chat-tab-search,
  .nj-chat-tab-search.glass-search {
    height: 38px !important;
    min-height: 38px !important;
    padding: 0 12px !important;
    border-radius: 19px !important;
  }
}

/* 聊天分类标题容器 */
.nj-chat-tab-section-title {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  padding: 0 14px 10px 14px !important;
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  overflow: hidden !important;
}

/* 隐藏原始分类标题内容 */
.nj-chat-tab-section-title > * {
  display: none !important;
}

/* 自定义聊天分类标签 */
.nj-chat-tab-section-title::before {
  content: "所有聊天 5" !important;  /*可自定义 */
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: 28px !important;
  padding: 0 12px !important;
  border-radius: 999px !important;
  background: var(--tg-blue-soft) !important;
  color: var(--tg-blue-deep) !important;
  font-size: 12px !important;
  line-height: 1 !important;
  font-weight: 700 !important;
}

/* 清理分类标题额外伪元素 */
.nj-chat-tab-section-title::after {
  content: none !important;
  display: none !important;
}

/* 聊天列表顶部生日提示 */
.nj-chat-tab-list::before {
  content: "添加您的生日！让您的联系人知道您何时庆祝生日";  /*可自定义 */
  display: block;
  margin: 0 14px 8px 14px;
  padding: 10px 14px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--tg-surface) 90%, transparent);
  border: 1px solid var(--tg-line);
  color: var(--tg-muted);
  font-size: 12px;
  line-height: 1.35;
}

/* 聊天列表容器 */
.nj-chat-tab-list {
  padding: 0 0 calc(82px + var(--nuo-safe-bottom, 0px)) 0 !important;
  background: var(--tg-bg) !important;
}

/* 单条聊天项目 */
.nj-chat-item {
  position: relative !important;
  display: flex !important;
  align-items: flex-start !important;
  gap: 12px !important;
  margin: 0 !important;
  padding: 10px 14px !important;
  background: var(--tg-bg) !important;
  border: none !important;
  border-bottom: 1px solid var(--tg-line) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* 聊天项目按压或悬浮背景 */
.nj-chat-item:hover {
  background: color-mix(in srgb, var(--tg-surface) 42%, transparent) !important;
}

/* 聊天头像容器 */
.nj-chat-item-avatar {
  position: relative !important;
  z-index: 1 !important;
  width: 52px !important;
  height: 52px !important;
  min-width: 52px !important;
  border-radius: 50% !important;
  overflow: visible !important;
  background: var(--tg-surface-2) !important;
}

/* 聊天头像图片 */
.nj-chat-item-avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 50% !important;
}

/* 聊天名称保持在头像背景装饰上方 */
.nj-chat-item-name {
  position: relative !important;
  z-index: 1 !important;
}

/* 聊天预览文字保持在头像背景装饰上方 */
.nj-chat-item-preview {
  position: relative !important;
  z-index: 1 !important;
}

/* 时间与图钉保持在名称同一行 */
.nj-chat-item-time {
  position: static !important;
  z-index: 1 !important;
  margin-left: auto !important;
  flex-shrink: 0 !important;
  background: rgba(140, 150, 160, 0.12) !important;
  color: #8895a1 !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  line-height: 1 !important;
  padding: 4px 8px !important;
  border-radius: 12px !important;
}

/* 深色模式时间胶囊 */
[data-color-scheme="dark"] .nj-chat-item-time {
  background: rgba(255, 255, 255, 0.12) !important;
  color: #a0b0c0 !important;
}

/* 未读徽标固定在头像右下角 */
.nj-chat-item-unread-badge {
  position: absolute !important;
  right: -4px !important;
  bottom: -4px !important;
  top: auto !important;
  min-width: 22px !important;
  height: 22px !important;
  padding: 0 6px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  border-radius: 999px !important;
  background: var(--tg-badge) !important;
  color: #fff !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  box-shadow: 0 0 0 2px #fff !important;
  z-index: 2 !important;
}

/* 深色模式未读徽标描边 */
[data-color-scheme="dark"] .nj-chat-item-unread-badge {
  box-shadow: 0 0 0 2px var(--tg-bg) !important;
}

/* 移除系统置顶图标 */
.nj-chat-item-pinned::before {
  content: none !important;
  display: none !important;
}

/* 置顶聊天的时间胶囊布局 */
.nj-chat-item-pinned .nj-chat-item-time {
  display: inline-flex !important;
  align-items: center !important;
  gap: 4px !important;
  padding: 4px 8px 4px 6px !important;
}

/* 置顶聊天的图钉 */
.nj-chat-item-pinned .nj-chat-item-time::before {
  content: "📌"; /*可自定义 */
  font-size: 13px !important;
  line-height: 1 !important;
  filter: grayscale(100%) opacity(0.6); /*想让图钉恢复彩色，删除这一行 */
}

/* 隐藏置顶聊天时间内的系统图标 */
.nj-chat-item-pinned .nj-chat-item-time > * {
  display: none !important;
}

/* 头像模糊背景装饰 */
.nj-chat-item {
  --nj-item-deco-1-image: var(--nj-item-avatar-url);
  --nj-item-deco-1-top: 0;
  --nj-item-deco-1-left: 0;
  --nj-item-deco-1-width: 100%;
  --nj-item-deco-1-height: 100%;
  --nj-item-deco-1-size: cover;
  --nj-item-deco-1-filter: blur(18px) saturate(1.3);
  --nj-item-deco-1-opacity: var(--tg-decor-opacity);
  --nj-item-deco-1-z: 0;
}

/* 有未读徽标的聊天左侧显示蓝色提示线 */
.nj-chat-item:has(.nj-chat-item-unread-badge) {
  box-shadow: inset 3px 0 0 var(--tg-highlight) !important;
}

/* 免打扰聊天变淡 */
.nj-chat-item[data-muted="true"] {
  opacity: 0.55;
}

/* 刚收到新消息时使用蓝色闪烁 */
@keyframes nj-item-flash-tg {
  0% {
    background: var(--tg-flash-color);
  }

  100% {
    background: transparent;
  }
}

/* 新消息闪烁效果 */
.nj-chat-item[data-flash="true"] {
  animation: nj-item-flash-tg 1.2s ease-out;
}

/* 角色生成回复时头像轻微呼吸 */
.nj-chat-item[data-generating="true"] .nj-chat-item-avatar {
  animation: nj-breathe 2s ease-in-out infinite;
}

/* 切换进入聊天页面时列表错落淡入 */
[data-tab-anim="enter"][data-active-tab="chat"] .nj-chat-item {
  animation: nj-item-fade-up 0.3s both;
  animation-delay: calc(min(var(--nj-item-index, 0), 6) * 25ms);
}

/* 朋友圈评论与点赞容器 */
.nj-moments-engagement {
  background: var(--tg-surface) !important;
  border: 1px solid var(--tg-line) !important;
  border-radius: 12px !important;
  padding: 8px 12px !important;
}

/* 朋友圈点赞文字 */
.nj-moments-likes {
  color: var(--tg-text) !important;
}

/* 朋友圈单条评论 */
.nj-moments-comment {
  color: var(--tg-text) !important;
}

/* 朋友圈评论作者名称 */
.nj-moments-comment-author {
  color: var(--tg-blue) !important;
  font-weight: 700 !important;
}

/* 朋友圈评论正文 */
.nj-moments-comment-content {
  color: var(--tg-text) !important;
}

/* 切换进入朋友圈时内容上滑淡入 */
[data-tab-anim="enter"][data-active-tab="moments"] .nj-moments-feed {
  animation: nj-tab-slide-up 0.35s both;
}

/* 悬浮底栏本体 */
.nj-tab-bottom-bar {
  position: fixed !important;
  left: 20px !important;
  right: 20px !important;
  bottom: calc(12px + var(--nuo-safe-bottom, 0px)) !important;
  transform: none !important;
  z-index: 80 !important;
  width: auto !important;
  max-width: 320px !important;
  margin: 0 auto !important;
  height: 60px !important;
  min-height: 0 !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: stretch !important;
  justify-content: space-between !important;
  padding: 6px !important;
  border-radius: 999px !important;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.08), 0 1px 3px rgba(0, 0, 0, 0.05) !important;
  backdrop-filter: blur(18px) !important;
  -webkit-backdrop-filter: blur(18px) !important;
  overflow: visible !important;
}

/* 浅色模式底栏 */
[data-color-scheme="light"] .nj-tab-bottom-bar {
  background: rgba(255, 255, 255, 0.96) !important;
  border: 1px solid rgba(0, 0, 0, 0.06) !important;
}

/* 深色模式底栏 */
[data-color-scheme="dark"] .nj-tab-bottom-bar {
  background: rgba(23, 33, 43, 0.94) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.3) !important;
}

/* 移除底栏额外伪元素 */
.nj-tab-bottom-bar::before,
.nj-tab-bottom-bar::after {
  display: none !important;
}

/* 底栏单个页面按钮 */
.nj-tab-bottom-item {
  position: relative !important;
  flex: 1 1 0% !important;
  height: 100% !important;
  min-height: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 3px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 999px !important;
  background: transparent !important;
  transform: none !important;
  box-shadow: none !important;
  font-size: 0 !important;
}

/* 浅色模式未选中底栏按钮 */
[data-color-scheme="light"] .nj-tab-bottom-item:not(.nj-tab-bottom-item-active) {
  color: #556270 !important;
}

/* 深色模式未选中底栏按钮 */
[data-color-scheme="dark"] .nj-tab-bottom-item:not(.nj-tab-bottom-item-active) {
  color: #8fa0ae !important;
}

/* 底栏图标 */
.nj-tab-bottom-icon {
  width: 22px !important;
  height: 22px !important;
  margin: 0 !important;
  font-size: 22px !important;
  line-height: 1 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  color: currentColor !important;
}

/* 隐藏系统底栏文字 */
.nj-tab-bottom-item span:not(.nj-tab-bottom-total-unread),
.nj-tab-bottom-item-label {
  display: none !important;
}

/* 自定义底栏文字样式 */
.nj-tab-bottom-item::after {
  display: block !important;
  font-size: 11px !important;
  line-height: 1 !important;
  font-weight: 700 !important;
  color: currentColor !important;
  white-space: nowrap !important;
}

/* 自定义聊天底栏文字 */
.nj-tab-bottom-item-chat::after {
  content: "聊天" !important;
}

/* 自定义动态底栏文字 */
.nj-tab-bottom-item-moments::after {
  content: "动态" !important;
}

/* 自定义收藏底栏文字 */
.nj-tab-bottom-item-favorites::after {
  content: "收藏" !important;
}

/* 自定义个人资料底栏文字 */
.nj-tab-bottom-item-profile::after {
  content: "个人资料" !important;
}

/* 浅色模式当前底栏按钮 */
[data-color-scheme="light"] .nj-tab-bottom-item-active {
  background: linear-gradient(180deg, #dff0ff 0%, #d5ebff 100%) !important;
  color: #139fe8 !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 1px 2px rgba(19, 159, 232, 0.08) !important;
}

/* 深色模式当前底栏按钮 */
[data-color-scheme="dark"] .nj-tab-bottom-item-active {
  background: linear-gradient(180deg, #2b4b6e 0%, #1f3a55 100%) !important;
  color: #58bdf6 !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.15), 0 1px 2px rgba(0, 0, 0, 0.3) !important;
}

/* 底栏未读数字 */
.nj-tab-bottom-total-unread {
  position: absolute !important;
  top: 4px !important;
  right: calc(50% - 24px) !important;
  min-width: 18px !important;
  height: 18px !important;
  padding: 0 5px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  border-radius: 999px !important;
  background: #4fb8f2 !important;
  color: #fff !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  line-height: 1 !important;
  box-shadow: 0 2px 4px rgba(79, 184, 242, 0.3) !important;
  z-index: 3 !important;
}

/* 隐藏动态底栏红点 */
.nj-tab-bottom-moments-dot {
  display: none !important;
}

/* 系统开启减少动画时关闭全部自定义动画 */
@media (prefers-reduced-motion: reduce) {
  #messaging-chat-tab,
  #messaging-moments-tab,
  #messaging-profile-tab,
  #messaging-favorites-tab,
  .nj-tab-bottom-bar {
    --nj-msg-card-transition: none;
    --nj-msg-card-active-transform: none;
    --nj-msg-card-hover-transform: none;
    --nj-msg-tabbar-active-transform: none;
    --nj-msg-fade-in-duration: 0s;
  }

  .nj-chat-item,
  .nj-chat-item[data-flash="true"],
  .nj-chat-item[data-generating="true"] .nj-chat-item-avatar,
  .nj-moments-feed {
    animation: none !important;
    animation-delay: 0s !important;
    transition: none !important;
  }
}

/*⁣⁠‍​‍​⁠​‌‌‌​‌‌⁠⁠‍​​⁠​⁠​⁠⁠‌‍​⁠‌​⁠⁠​⁠⁠‍‍⁠‌‌‌‍⁠​⁠​​‍​​​⁠⁠​​‍‍‍⁠⁠⁠​‌⁠⁣ 「赦免（灰） by atne」 — nuojiji messaging app theme */

/* ============================================
    赦免 by atne
    禁二传二改 自定义和适配调整在开头🤍标注
    仅适配糯叽机消息 App
   ============================================ */

/* ----------🤍custom🤍---------- */
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab,
.nj-tab-bottom-bar {

  /* 主题色 */
 --primary-color: #eeeeee;
  --secondary-color: #f6f6f6;
  --tertiary-color: #b2b2b2;
  --quaternary-color: #e4e4e4;

  /* 搜索框占位符 */
  --search-placeholder: "祈求你不要出現";

  /* id / bio */
  --moments-handle: "thisisnot_atne";
  --moments-bio: "白水鉴心";

  /* 卡片图片 */
  --card-photo: url("https://atnefallhmhz.vercel.app/f/avatar-ox8x4r.jpeg");

  /* 卡片气泡文案 */
  --card-them-text: "멈춰있는 시간들이 흘러가네요";
  --card-me-text: "굳어 있던 내 몸이 녹아내렸어요";
}

/* ----------🤍end🤍---------- */

/* ----------variables---------- */
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab,
.nj-tab-bottom-bar {
  --nj-msg-bg: #ffffff;
  --nj-msg-card-bg: #ffffff;
  --nj-msg-card-bg-pinned: var(--primary-color);
  --nj-msg-card-border: none;
  --nj-msg-card-padding: 13px 20px;
  --nj-msg-avatar-shadow: none;
  --nj-msg-chat-search-radius: 8px;
  --nj-msg-moments-cover-height: 320px;
  --nj-msg-tabbar-bg: #ffffff;
  --nj-msg-tabbar-active-transform: none;
}

/* ----------1. tab bar---------- */

.nj-tab-bottom-bar {
  box-sizing: border-box !important;
  justify-content: space-between !important;
  min-height: calc(69px + max(0px, var(--nuo-safe-bottom) - 12px)) !important;
  padding: 0 22px max(0px, var(--nuo-safe-bottom) - 12px) !important;
  border: none !important;
  border-top: 1px solid var(--primary-color) !important;
  background: #ffffff !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  filter: none !important;
  box-shadow: none !important;
}

.nj-tab-bottom-bar::before {
  content: none !important;
  display: none !important;
}

.nj-tab-bottom-bar > *,
.nj-tab-bottom-bar > *::before,
.nj-tab-bottom-bar > *::after,
.nj-tab-bottom-bar::after {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

.nj-tab-bottom-bar::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  bottom: max(0px, var(--nuo-safe-bottom) - 12px) !important;
  height: 1px !important;
  background: var(--primary-color) !important;
  pointer-events: none !important;
}

.nj-tab-bottom-item {
  box-sizing: border-box !important;
  flex: 0 1 68px !important;
  min-width: 0 !important;
  height: 42px !important;
  min-height: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  border-radius: 8px !important;
  background: #ffffff !important;
  border: 1px solid var(--primary-color) !important;
}

.nj-tab-bottom-item-active {
  background: var(--quaternary-color) !important;
  border-color: transparent !important;
  box-shadow: 0 1px 3px rgba(0,0,0,.05) !important;
}

.nj-tab-bottom-icon {
  display: none !important;
}

.nj-tab-bottom-item::after {
  display: block !important;
  font-size: 13px !important;
  font-weight: 400 !important;
  letter-spacing: .02em !important;
  line-height: 1 !important;
  white-space: pre !important;
  text-align: center !important;
  pointer-events: none !important;
  color: #8e8e8e !important;
  -webkit-text-fill-color: #8e8e8e !important;
  text-decoration: none !important;
}

.nj-tab-bottom-item-chat::after      { content: "\0000a0chat\0000a0"; }
.nj-tab-bottom-item-profile::after   { content: "\0000a0profile\0000a0"; }
.nj-tab-bottom-item-moments::after   { content: "\0000a0moment\0000a0"; }
.nj-tab-bottom-item-favorites::after { content: "\0000a0collection\0000a0"; }

.nj-tab-bottom-item-active::after {
  content: "\0000a0ᗜ ⩊ ᯇ\0000a0";
  font-size: 12px !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  text-decoration: line-through !important;
  text-decoration-color: #ffffff !important;
  text-decoration-thickness: 0.5px !important;
}

.nj-tab-bottom-total-unread,
.nj-tab-bottom-moments-dot {
  background: var(--tertiary-color) !important;
  border: none !important;
}

/* ----------2. header---------- */

.nj-chat-tab-header {
  box-sizing: border-box !important;
  display: flex !important;
  align-items: center !important;
  gap: 0 !important;
  flex-shrink: 0 !important;
  height: calc(48px + var(--nuo-safe-top)) !important;
  min-height: calc(48px + var(--nuo-safe-top)) !important;
  padding: calc(var(--nuo-safe-top) + 2px) 20px 2px !important;
  border-bottom: 1px solid var(--primary-color) !important;
  box-shadow: none !important;
  filter: none !important;
}

.nj-chat-tab-header > * {
  transform: translateY(-6px) !important;
}

.nj-chat-tab-header-back {
  box-sizing: border-box !important;
  position: relative !important;
  flex: 0 0 auto !important;
  width: 40px !important;
  min-width: 40px !important;
  height: 40px !important;
  padding: 0 !important;
  margin: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  font-size: 0 !important;
  overflow: visible !important;
}

.nj-chat-tab-header-back > *,
.nj-chat-tab-header-back svg,
.nj-chat-tab-header-back img {
  display: none !important;
}

.nj-chat-tab-header-back::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  left: 6px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: 30px !important;
  height: 30px !important;
  border-radius: 50% !important;
  background: url("https://atnefallhmhz.vercel.app/f/pearl-a2g1un.jpeg") center / cover no-repeat !important;
  pointer-events: none !important;
}

.nj-chat-tab-header-title-btn {
  box-sizing: border-box !important;
  display: inline-flex !important;
  align-items: center !important;
  flex: 0 0 auto !important;
  height: 40px !important;
  padding: 0 !important;
  margin-left: 10px !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
}

.nj-chat-tab-header-title-btn svg,
.nj-chat-tab-header-title-btn svg * {
  color: var(--tertiary-color) !important;
  stroke: var(--tertiary-color) !important;
  fill: none !important;
}

.nj-chat-tab-header-edit {
  margin-left: auto !important;
  display: inline-flex !important;
  align-items: center !important;
}

.nj-chat-tab-header-edit > *,
.nj-chat-tab-header-edit svg,
.nj-chat-tab-header-edit img {
  display: none !important;
}

.nj-chat-tab-header-edit::after {
  content: "｜：無赦免" !important;
  display: block !important;
  white-space: nowrap !important;
  font-size: 14.5px !important;
  font-weight: 350 !important;
  line-height: 1 !important;
  color: var(--tertiary-color) !important;
  -webkit-text-fill-color: var(--tertiary-color) !important;
}

/* ----------3. search---------- */

.nj-chat-tab-search-wrap {
  flex-shrink: 0 !important;
  padding: 24px 20px !important;
}

.nj-chat-tab-search {
  position: relative !important;
  border: 1px solid var(--primary-color) !important;
  box-shadow: none !important;
  border-radius: 8px !important;
}

.nj-chat-tab-search > svg {
  stroke: transparent !important;
  fill: none !important;
  background-color: var(--tertiary-color) !important;
  -webkit-mask: url("https://img.icons8.com/?size=100&id=VdLImXvBGi2a&format=png&color=000000") center / contain no-repeat !important;
  mask: url("https://img.icons8.com/?size=100&id=VdLImXvBGi2a&format=png&color=000000") center / contain no-repeat !important;
}

.nj-chat-tab-search input::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
}

.nj-chat-tab-search:has(input:placeholder-shown)::after {
  content: "\0000a0" var(--search-placeholder) "\0000a0" !important;
  position: absolute !important;
  left: 44px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  white-space: pre !important;
  font-size: 15px !important;
  line-height: 1 !important;
  color: var(--nj-msg-text-muted, #8b95a1) !important;
  -webkit-text-fill-color: var(--nj-msg-text-muted, #8b95a1) !important;
  text-decoration: line-through !important;
  text-decoration-color: var(--tertiary-color) !important;
  text-decoration-thickness: 0.5px !important;
  pointer-events: none !important;
}

/* ----------4. card---------- */

.nj-chat-tab-decor-top {
  box-sizing: border-box !important;
  display: block !important;
  position: relative !important;
  flex-shrink: 0 !important;
  width: auto !important;
  max-width: none !important;
  align-self: stretch !important;
  height: 168px !important;
  margin: 0 20px 12px !important;
  padding: 0 !important;
  border: 1px solid var(--primary-color) !important;
  border-radius: 8px !important;
  background-color: #ffffff !important;
