}

.tm-suggestion-item:last-child {
  border-bottom: none !important;
}

.tm-suggestion-direction {
  color: #777 !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  letter-spacing: 0.4px !important;
}

.tm-suggestion-text {
  color: #444 !important;
  font-size: 13px !important;
  line-height: 1.45 !important;
}

.tm-suggestion-reroll {
  color: #777 !important;
}


/* =========================================================
   14. 右键 / 长按菜单
   ========================================================= */

.tm-context-menu {
  background: rgba(255,255,255,0.96) !important;
  border: 1px solid #d8d8d4 !important;
  border-radius: 10px !important;
  box-shadow: 0 8px 24px rgba(0,0,0,0.12) !important;
}

.tm-context-menu button {
  color: #444 !important;
}

.tm-ctx-delete {
  color: #a55 !important;
}


/* =========================================================
   15. 手机窄屏适配
   ========================================================= */

@media (max-width: 520px) {
  :root {
    --id-card-width: 90vw;
    --id-body-max-height: 420px;

    /* 【可改：手机端头像大小】 */
    --id-avatar-w: 96px;
    --id-avatar-h: 124px;

    /* 【可改：手机端头像位置】 */
    --id-avatar-left: 18px;
    --id-avatar-top: 80px;

