        color: #444444 !important; 
        background: #f5f5f6 !important; 
        border: 1px solid #dedee3 !important; 
        border-radius: 6px !important;
    }

    /* 强行覆盖右上角的金星星标为银灰色 */
    #world-book-screen .wb-list-row [class*="star"], 
    #world-book-screen .wb-list-row [class*="pin"],
    #world-book-screen .wb-list-row [class*="global"],
    #world-book-screen .wb-list-row .wb-spine-global-pin {
        color: #888888 !important;
    }
    #world-book-screen .wb-list-row [class*="star"] svg,
    #world-book-screen .wb-list-row [class*="pin"] svg,
    #world-book-screen .wb-list-row [class*="global"] svg {
        fill: #888888 !important;
        stroke: #888888 !important;
    }

    /* ===== 修复：底部搜索框（日间毛玻璃） ===== */
    #world-book-screen .wb-shelf-filter-bar {
        position: fixed !important; left: 50% !important; bottom: 20px !important;
        transform: translateX(-50%) !important; display: flex !important; flex-wrap: wrap !important;
        align-items: center !important; gap: 8px !important; width: 90% !important;
        padding: 0 !important; background: transparent !important; border: none !important;
        z-index: 900 !important;
    }
    #world-book-screen .wb-shelf-search-box {
        width: 100% !important; padding: 8px 12px !important;
        background: rgba(255, 255, 255, 0.4) !important; /* 降低不透明度，增强通透感 */
        border: 1px solid rgba(255, 255, 255, 0.6) !important; /* 边框柔和 */
        border-radius: 14px !important;
        -webkit-backdrop-filter: blur(16px) !important; backdrop-filter: blur(16px) !important;
        box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06) !important;
    }
    /* 强制内部输入框透明 */
    #world-book-screen .wb-shelf-search-input,
    #world-book-screen .wb-shelf-search-box input {
        color: #171717 !important; text-align: center !important; font-size: 16px !important;
        background: transparent !important;
        background-color: transparent !important;
        border: none !important;
        box-shadow: none !important;
        outline: none !important;
    }
    #world-book-screen .wb-shelf-search-input::placeholder,
    #world-book-screen .wb-shelf-search-box input::placeholder { 
        color: #888888 !important; 
    }

    /* ===== 打开书本后的白色详情页 ===== */
    #world-book-screen .wb-modal-overlay { background: rgba(0, 0, 0, 0.3) !important; }
    #world-book-screen .wb-book-modal {
        color: #171717 !important;
        background: #ffffff !important;
        border-color: #dedee3 !important;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1) !important;
    }
    #world-book-screen .wb-left-page,
    #world-book-screen .wb-right-page {
        color: #171717 !important;
        background: #ffffff !important;
        border-color: #e2e2e6 !important;
        box-shadow: none !important;
    }
    #world-book-screen .wb-cover-title,
    #world-book-screen .wb-cover-subtitle,
    #world-book-screen .wb-cover-description,
    #world-book-screen .wb-cover-open-hint { color: #171717 !important; }
    #world-book-screen .wb-tabs { background-color: #ffffff !important; border-color: #e1e1e5 !important; }
    #world-book-screen .wb-tab { color: #666666 !important; background-color: #ffffff !important; border-color: #e1e1e5 !important; }
    #world-book-screen .wb-tab.active { color: #171717 !important; background-color: #f2f2f4 !important; }

    /* 日间银灰指示条，去除黄色发光 */
    #world-book-screen .wb-tab-indicator { 
        background: #cccccc !important; 
        box-shadow: none !important; 
    }

    /* ===== 搜索条目、词条卡片白底+深灰字 ===== */
    #world-book-screen .wb-search-bar {
        color: #171717 !important;
        background: #f5f5f6 !important;
        border: 1px solid #e0e0e4 !important;
        border-radius: 12px !important;
    }
    #world-book-screen .wb-search-input { color: #171717 !important; background: transparent !important; border: none !important; }
    #world-book-screen .wb-search-input::placeholder { color: #888888 !important; }

    #world-book-screen .wb-entry {
        color: #171717 !important;
        background: #ffffff !important;
        border-color: #e2e2e6 !important;
        border-left: 2px solid #929aa7 !important;
        border-radius: 12px !important;
        box-shadow: 0 3px 12px rgba(0, 0, 0, 0.045) !important;
    }
    #world-book-screen .wb-entry-title,
    #world-book-screen .wb-entry-keywords,
    #world-book-screen .wb-entry-content { color: #242424 !important; }

    /* 日间银白灰标签 */
    #world-book-screen .wb-view-tag { 
        color: #444444 !important; 
        background: #f5f5f6 !important; 
        border: 1px solid #e0e0e4 !important; 
        border-radius: 8px !important;
    }

    /* 日间设定页左侧标签去除金色 */
    #world-book-screen .wb-settings-info-row > *:first-child,
    #world-book-screen .wb-settings-row-label {
        color: #555555 !important;
    }

    /* 词条编辑框、设置小格 */
    #world-book-screen .wb-entry-input,
    #world-book-screen .wb-entry-textarea,
    #world-book-screen .wb-expand-textarea {
        color: #171717 !important; background-color: #ffffff !important; border-color: #d8d8de !important;
    }
    #world-book-screen .wb-entry-input::placeholder,
    #world-book-screen .wb-entry-textarea::placeholder,
    #world-book-screen .wb-expand-textarea::placeholder { color: #888888 !important; }
    #world-book-screen .wb-control-item,
    #world-book-screen .wb-settings-info-row { color: #242424 !important; background-color: #ffffff !important; border-color: #e2e2e6 !important; }

    /* 详情页右上角操作按钮改为纯白底 + 深灰图标 */
    #world-book-screen .wb-modal-controls { color: #242424 !important; background-color: transparent !important; }
    #world-book-screen .wb-modal-control-btn {
        color: #333333 !important;
        background: #ffffff !important;
        background-image: none !important;
        border: 1px solid #dedee3 !important;
        box-shadow: 0 2px 8px rgba(0,0,0,0.06) !important;
        border-radius: 50% !important;
    }
    #world-book-screen .wb-modal-control-btn svg { 
        color: #333333 !important; 
        stroke: #333333 !important; 
    }
    #world-book-screen .wb-modal-control-btn.editing {
        color: #ffffff !important;
        background: #333333 !important;
        background-image: none !important;
        border-color: #333333 !important;
    }
    #world-book-screen .wb-modal-control-btn.editing svg {
        color: #ffffff !important; 
        stroke: #ffffff !important; 
    }

    /* 其他按钮 */
    #world-book-screen .wb-add-entry-btn { color: #333333 !important; background: #ffffff !important; border: 1px solid #dedee3 !important; }
    #world-book-screen .wb-entry-fold-btn, #world-book-screen .wb-entry-grip { color: #555555 !important; background: transparent !important; border-color: #dedee3 !important; }
    #world-book-screen .wb-right-page-number { color: #888888 !important; border-color: #e2e2e6 !important; }

    /* 放大编辑框、新建书等弹窗 */
    #world-book-screen .wb-expand-modal, #world-book-screen .wb-new-modal {
        color: #171717 !important; background-color: #ffffff !important; border-color: #dedee3 !important;
    }
    #world-book-screen .wb-expand-modal-header, #world-book-screen .wb-new-modal-header {
        color: #171717 !important; background-color: #f7f7f8 !important; border-color: #dedee3 !important;
    }
    #world-book-screen .wb-expand-modal-title, #world-book-screen .wb-new-modal-title, #world-book-screen .wb-new-modal-subtitle { color: #171717 !important; }
    #world-book-screen .wb-modal-close, #world-book-screen .wb-expand-modal-close {
        color: #333333 !important; background-color: #f5f5f6 !important; border-color: #dedee3 !important;
    }

    /* 通用输入控件 */
    #world-book-screen input,
    #world-book-screen textarea,
    #world-book-screen select {
        color: #171717 !important; background-color: #ffffff !important; border-color: #d8d8de !important;
    }
    #world-book-screen input::placeholder,
    #world-book-screen textarea::placeholder { color: #888888 !important; }
    #world-book-screen hr { border-color: #e1e1e5 !important; }
}
/* =====================================================
   修复 1：日夜间都保留七款书籍封面
   放在整个 CSS 最末尾
   ===================================================== */

/* 封面图片统一从书籍卡片继承 */
.wb-book-spine-body,
.wb-stacked-book.top,
.wb-faceout-cover {
    background-image: var(--wb-cover-image) !important;
    background-size: cover !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;
}

/* 避免日间模式的通用背景规则覆盖封面图片 */
@media (prefers-color-scheme: light) {
    .wb-book-spine-body,
    .wb-stacked-book.top,
    .wb-faceout-cover {
        background-image: var(--wb-cover-image) !important;
        background-size: cover !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
        background-color: transparent !important;
    }
}
/* =====================================================
   修复 2：夜间分列视图
   与日间统一卡片布局，只改变配色
   ===================================================== */

@media (prefers-color-scheme: dark) {

    /* 列表区域背景 */
    #world-book-screen .wb-list-view,
    #world-book-screen .wb-library {
        background: #000000 !important;
        color: #e8ebf0 !important;
    }

    /* 卡片外形与日间保持一致 */
    #world-book-screen .wb-list-row {
        box-sizing: border-box !important;
        display: flex !important;
        align-items: center !important;

        margin-bottom: 8px !important;
        padding: 14px 16px !important;

        border: 1px solid #3c3f46 !important;
        border-radius: 14px !important;

        /* 黑曜石银灰渐变 */
        background: linear-gradient(
            145deg,
            #24262b 0%,
            #17181c 55%,
            #101114 100%
        ) !important;
        background-image: linear-gradient(
            145deg,
            #24262b 0%,
            #17181c 55%,
            #101114 100%
        ) !important;

        box-shadow:
            inset 0 1px 0 rgba(255,255,255,.06),
            0 3px 10px rgba(0,0,0,.22) !important;
    }

    /* 左侧圆形图标 */
    #world-book-screen .wb-list-spine {
        border-radius: 50% !important;
        background: linear-gradient(
            135deg,
            #d9dde4,
            #858b96
        ) !important;
        border: 1px solid #aeb4be !important;
        box-shadow: inset 0 1px 2px rgba(255,255,255,.28) !important;
    }

    #world-book-screen .wb-list-spine svg,
    #world-book-screen .wb-list-spine path,
    #world-book-screen .wb-list-spine i {
        color: #24262b !important;
        stroke: #24262b !important;
        fill: #24262b !important;
    }

    /* 标题与描述 */
    #world-book-screen .wb-list-title {
        color: #f0f2f6 !important;
    }

    #world-book-screen .wb-list-desc,
    #world-book-screen .wb-list-count,
    #world-book-screen .wb-list-author {
        color: #aeb4bf !important;
    }

    /* 标签：银灰底、深色文字 */
    #world-book-screen .wb-list-tag {
        color: #e2e6ed !important;
        background: #30333a !important;
        border: 1px solid #555b66 !important;
        border-radius: 6px !important;
    }
}
